-- Перенос всех курсов из файлов сайта (src/data/courses/*.js) в таблицу courses.
--
-- Владелец курсов — первый администратор (access >= 100): он должен хотя бы раз
-- войти на сайт, чтобы появиться в таблице users. Иначе запрос упадёт на NOT NULL.
--
-- Новые курсы добавляются закрытыми (disabled = 1): целиком их видит только
-- администратор, остальные — плашку «Ведётся работа». Открыть курсы:
--   UPDATE courses SET disabled = 0 WHERE id IN ('unity-first-game', 'html-css-first-site');
--
-- Запрос можно запускать повторно: содержимое курсов перезапишется, а открыт курс
-- или закрыт — останется как было. Порядок в каталоге задаёт created_at:
-- курсы идут так же, как в src/data/courses.js.

SET NAMES utf8mb4;

SET @owner = (SELECT id FROM users WHERE access >= 100 ORDER BY id LIMIT 1);

-- Основа Unity. Первый проект: 10 стр.
INSERT INTO courses (id, title, subtitle, accent, section, difficulty, level, duration, image, video, chips, github, author, certificate, about, pages, user_id, disabled, created_at, updated_at)
VALUES ('unity-first-game',
        'Основа Unity. Первый проект',
        'Разработка игры на Unity с нуля: от установки движка до готового 2D-платформера на Android.',
        'unity',
        'unity',
        2,
        'Для начинающих',
        '10 уроков',
        '/img/courses/unity-first-game/cover.jpg',
        NULL,
        '[\"Unity\",\"C#\",\"2D\"]',
        'https://github.com/DanyaBooba/UnityEducation',
        '{\"name\":\"Даниил Дыбка\",\"email\":\"daniil@dybka.ru\",\"telegram\":\"https://ddybka.t.me\"}',
        NULL,
        '[{\"block\":\"p\",\"content\":\"Создадим первый настоящий проект на Unity. Установим игровой движок, познакомимся с интерфейсом программы, научимся создавать сцены, персонажей и врагов. В конце курса соберём 2D-платформер, который запускается на телефоне: с управлением, врагами, здоровьем и меню.\"},{\"block\":\"h2\",\"content\":\"Что вы получите\"},{\"block\":\"p\",\"content\":\"Все десять уроков — это один непрерывный проект. Каждый урок добавляет к игре новую работающую часть.\"},{\"block\":\"ul\",\"items\":[\"Проект в Unity и первая сборка на телефон\",\"Локация по собственным правилам: платформы, фон, физика и коллизия\",\"Персонаж с движением, прыжком и разворотом\",\"Враги, теги, урон и пополнение здоровья\",\"Сцена меню и интерфейс\"]},{\"block\":\"h2\",\"content\":\"Кому подойдёт\"},{\"block\":\"p\",\"content\":\"Курс рассчитан для новичков. Опыт в программировании и Unity не нужен. Синтаксис языка программирования C# мы разбираем ровно в том объёме, который нужен для текущего шага.\"},{\"block\":\"h2\",\"content\":\"Как проходить\"},{\"block\":\"p\",\"content\":\"Читайте урок и сразу повторяйте шаги в своём проекте. Это главное правило курса: страница, прочитанная без движка на экране, не даёт почти ничего.\"},{\"block\":\"ol\",\"items\":[\"Откройте урок и свой проект Unity рядом\",\"Повторите шаги, не копируя код целиком — пишите самостоятельно\",\"Запустите игру и проверьте результат до перехода к следующему уроку\"]},{\"block\":\"note\",\"content\":\"Если что-то не работает, сравните свой код с исходниками на GitHub — ссылка есть в шапке курса и в плане уроков.\"},{\"block\":\"h2\",\"content\":\"Что потребуется\"},{\"block\":\"table\",\"head\":[\"Что\",\"Подробности\"],\"rows\":[[\"Компьютер\",\"Windows 7 и новее или macOS 10.13.6 и новее\"],[\"Unity\",\"Unity Hub и любая LTS-версия редактора\"],[\"Редактор кода\",\"Visual Studio, Rider или VS Code\"],[\"Android (по желанию)\",\"Модуль Android Build Support для сборки на телефон\"]]},{\"block\":\"p\",\"content\":\"Отдельно искать графику не обязательно. Готовый пакет спрайтов скачивается прямо в пятом уроке, перед началом работы над платформером.\"}]',
        '[{\"slug\":\"1\",\"title\":\"1. Про игровой движок Unity\",\"short\":\"Про игровой движок Unity\",\"content\":[{\"block\":\"p\",\"content\":\"Здравствуйте, добро пожаловать на курс по разработке игр на Unity. В рамках данного курса мы познакомимся с интерфейсом Unity, разработаем собственный игровой проект и протестируем его на реальном устройстве.\"},{\"block\":\"h2\",\"content\":\"Как создаются игры\"},{\"block\":\"p\",\"content\":\"Начнем с основ. Каким образом разрабатываются игры? Для разработки игр используются языки программирования. В качестве языка может быть выбран любой язык программирования: `Python`, `C#` или же `Java`.\"},{\"block\":\"quote\",\"content\":\"Язык программирования — формальный язык, предназначенный для записи компьютерных программ.\"},{\"block\":\"p\",\"content\":\"Игра представляет собой интерфейс, локации. В игре мы управляем персонажем, который может взаимодействовать с окружающим миром. Все это может быть разработано с помощью языка программирования.\"},{\"block\":\"p\",\"content\":\"Разработку игры можно начать на `«чистом»` языке программирования, не используя никакие библиотеки. Можно добавить библиотеки для упрощения разработки игры. Либо использовать игровые движки. В рамках курса мы будем использовать игровой движок Unity.\"},{\"block\":\"quote\",\"content\":\"«Чистый язык программирования» — использование языка программирования без дополнительных модулей и библиотек.\"},{\"block\":\"p\",\"content\":\"Игровой движок сильно упрощает разработку игры. К примеру, для создания своей игры на «чистом» языке программирования без библиотек и компонентов вам придется разрабатывать интерфейс, физику и логику.\"},{\"block\":\"p\",\"content\":\"В игровой движок Unity все нужные компоненты и библиотеки уже включены по умолчанию, благодаря чему разработка игры будет сильно упрощена.\"},{\"block\":\"h2\",\"content\":\"Выбранный игровой движок\"},{\"block\":\"p\",\"content\":\"Стоит акцентировать свое внимание на выбранном игровом движке. Почему мы используем игровой движок стало понятно. Осталось ответить на вопрос, почему выбранный игровой движок именно Unity.\"},{\"block\":\"quote\",\"content\":\"Unity — кроссплатформенная среда разработки компьютерных игр, позволяющая создавать приложения, работающие на более чем 25 различных платформах.\"},{\"block\":\"p\",\"content\":\"У Unity есть ряд плюсов. Приведу данные в виде таблицы:\"},{\"block\":\"table\",\"head\":[\"Игровой движок\",\"Простой интерфейс\",\"Модули\",\"Поддержка платформ\",\"Создание крупных проектов\"],\"rows\":[[\"Unity\",\"`Да`\",\"`Да`\",\"`Да`\",\"`Да `\"],[\"Godot\",\"`Да`\",\"`Да`\",\"`Да`\",\"Нет\"],[\"Unreal Engine\",\"Нет\",\"Нет\",\"`Да`\",\"`Да`\"],[\"RPG Maker\",\"`Да`\",\"Нет\",\"Нет\",\"Нет\"]]},{\"block\":\"p\",\"content\":\"Важно понимать следующую мысль: если начать изучать создание игр на различных слабых игровых движках или решениях, в будущем перейти к крупным проектам уже не получится. Поэтому я рекомендую начинать изучение сразу с хороших решений. Unity является лучшим решением для новичков. С помощью Unity можно создавать не только простые игры, но и проекты любой сложности.\"},{\"block\":\"h2\",\"content\":\"Разработка на Unity\"},{\"block\":\"p\",\"content\":\"Поговорим еще немного про разработку и перейдем к установке Unity. Разработка игры на Unity происходит с помощью системы компонентов. Для того, чтобы добавить текстуру на объект — добавляется компонент «SpriteRenderer». Для добавления физики используется компонент Rigidbody 2D. И так далее. В будущем мы еще познакомимся с компонентами Unity.\"}]},{\"slug\":\"2\",\"title\":\"2. Установка Unity на компьютер\",\"short\":\"Установка Unity на компьютер\",\"content\":[{\"block\":\"p\",\"content\":\"Перейдем к установке Unity на компьютер. Установить можно на операционную систему Windows, macOS, Linux. Ход установки не будет отличаться на данный операционных системах. Лично я буду использовать macOS для установки.\"},{\"block\":\"h2\",\"content\":\"Скачиваем Unity Hub\"},{\"block\":\"p\",\"content\":\"Для установки игрового движка Unity нам нужно установить Unity Hub. Для этого переходим на сайт Unity.\"},{\"block\":\"p\",\"content\":\"[https://unity.com/ru/download](https://unity.com/ru/download)\"},{\"block\":\"p\",\"content\":\"Выбираем платформу для скачивания и устанавливаем Unity Hub.\"},{\"block\":\"quote\",\"content\":\"Unity Hub — это простейший способ активации лицензий и управления учетной записью Unity.\"},{\"block\":\"p\",\"content\":\"Ссылки на скачивание:\"},{\"block\":\"ul\",\"items\":[\"[Скачать для Windows](https://public-cdn.cloud.unity3d.com/hub/prod/UnityHubSetup.exe?_ga=2.149436726.1412396104.1686260592-625258726.1686260592)\",\"[Скачать для macOS](https://public-cdn.cloud.unity3d.com/hub/prod/UnityHubSetup.dmg?_ga=2.149436726.1412396104.1686260592-625258726.1686260592)\",\"[Скачать для Linux](https://docs.unity3d.com/hub/manual/InstallHub.html?_ga=2.149436726.1412396104.1686260592-625258726.1686260592#install-hub-linux)\"]},{\"block\":\"p\",\"content\":\"Производим установку программы на свой компьютер. После установки появится приложение с иконкой Unity и названием Unity Hub. Если не получается найти приложение — попробуйте воспользоваться поиском, впишите название программы: «Unity Hub».\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less2/less2__01.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"Это интерфейс Unity Hub. Прежде чем начать устанавливать игровой движок Unity и создавать свой проект, нам нужно зарегистрироваться. Воспользуйтесь иконкой слева вверху. Используйте «Sign up» для регистрации на сайте.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less2/less2__02.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"Введите почту, пароль и ваше имя. Для входа в аккаунт вам нужно будет использовать почту и пароль.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less2/less2__03.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"После регистрации вам нужно нажать на аккаунт в Unity Hub, нажать на «Manage licenses». У вас появится окно для управления лицензией приложения. Чтобы использовать игровой движок нам нужно активировать бесплатную лицензию.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less2/less2__04.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"Нажимаем кнопку «Add», появится список лицензий, нам нужно выбрать следующий вариант лицензии: «Get a free personal license». Принимаем правила Unity. После в списке лицензий у вас, как и у меня, появится «Personal» лицензия.\"},{\"block\":\"p\",\"content\":\"_К слову, вы можете обратить внимание, что моя лицензия активирована 19 октября 2018 года._\"},{\"block\":\"p\",\"content\":\"Отлично, мы активировали лицензию, теперь мы можем создавать игровые проекты без каких-либо ограничений. Теперь нам нужно установить игровой движок Unity.\"},{\"block\":\"note\",\"content\":\"Обычно Unity устанавливается на диск C:/ и занимает 10-20 Гб. Проверьте, хватает ли на вашей системе места для игрового движка.\"},{\"block\":\"p\",\"content\":\"Для установки Unity перейдем в пункт «Installs» в левом боковом меню. Здесь вам нужно нажать на «Install Editor» для установки игрового движка Unity.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less2/less2__05.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"Здесь появится окно, в котором нам нужно выбрать версию игрового движка Unity. Лично я рекомендую версию 2021 года с надписью LTS слева.\"},{\"block\":\"quote\",\"content\":\"LTS — это часть жизненного цикла программного обеспечения, которая означает, что стабильный релиз будет поддерживаться долгое время и будет считаться стандартной версией к распространению.\"},{\"block\":\"p\",\"content\":\"Сейчас у меня актуальная версия игрового движка Unity 2021 года: 2021.3.27f1. Если у вас другая версия, убедитесь, что она 2021 года и можете скачивать. Я выбираю версию 2021 года из-за ее относительной стабильности и наличия поддержки всех актуальных компонентов, которые мы будем использовать в разработке.\"},{\"block\":\"p\",\"content\":\"Нажимаем кнопку «Install» справа от выбранной версии. Следующее окно — выбор компонентов при установке. Обращаю внимание, что выбор компонентов при установке — важный процесс. Мы должны установить те компоненты, которые будем использовать при установке. Мы всегда сможем скачать их после установки, но рекомендую установить нужный пакет компонентов именно на данном шаге установки.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less2/less2__06.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"Для правильной работы игрового движка Unity нам нужно установить следующий пакет компонентов:\"},{\"block\":\"ul\",\"items\":[\"Visual Studio\",{\"text\":\"Android Build Support\",\"items\":[\"OpenJDK\",\"Android SDK & NDK Tools\"]},\"Windows Build Support (Mono)\"]},{\"block\":\"p\",\"content\":\"Остальные компоненты вы можете скачать по желанию. Учтите, что каждый дополнительный компонент будет занимать место на компьютере. Размер каждого компонента вы сможете узнать справа от компонента.\"},{\"block\":\"p\",\"content\":\"После выбора всех нужных компонентов размер Unity будет составлять 18.94 Гб на диске. Соглашаемся и нажимаем на «Continue».\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less2/less2__07.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"Завершающий шаг. Нам нужно согласиться с политикой конфиденциальности и нажать на «I have read and agree with the above terms and conditions». После нажимаем на «Continue». Соглашаемся с еще одной политикой конфиденциальности таким же образом. И вот она заветная кнопка — «Install». Нажимаем и начинаем установки игрового движка Unity.\"},{\"block\":\"h2\",\"content\":\"Проблемы при установке\"},{\"block\":\"p\",\"content\":\"Сама установка может занимать много времени. Обычно игровой движок Unity с выбранными пакетами устанавливается за 20 минут. При установке у вас могут возникнуть проблемы.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less2/less2__08.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"Слева внизу есть кнопка «Downloads». Если нажать на нее — появится окно, в котором отобразятся все актуальные установки. Сейчас я ничего не скачиваю, поэтому у меня пустой экран. В случае, если устанавливать игровой движок Unity — сверху отобразится установка игрового движка Unity и его компонентов.\"},{\"block\":\"p\",\"content\":\"Если у вас появятся проблемы при установке — вы можете нажать справа на крестик, чтобы отменить установку. Обычно, если возникает проблема при установке — справа появится восклицательный знак.\"},{\"block\":\"p\",\"content\":\"Чтобы исправить проблемы при установке — нажмите на крест, остановите установку, далее — пройдите в окно «Installs» и начните всю установку заново.\"}]},{\"slug\":\"3\",\"title\":\"3. Знакомство с интерфейсом движка\",\"short\":\"Знакомство с интерфейсом движка\",\"content\":[{\"block\":\"p\",\"content\":\"Перейдем наконец-то к созданию своего первого пробного проекта на Unity. Вот, что мы сделаем для начала: мы создадим проект, добавим на сцену какой-нибудь элемент и создадим .apk файл для установки на андроид или .exe для Windows.\"},{\"block\":\"h2\",\"content\":\"Создаем проект\"},{\"block\":\"p\",\"content\":\"Перейдем к созданию проекта. Для этого запустим Unity Hub. Во вкладке слева выбираем «Projects». Здесь находится вкладка со всеми вашими проектами. Если до этого вы не разрабатывали ничего — экран будет пустой.\"},{\"block\":\"p\",\"content\":\"В верхнем правом углу нажимаем на кнопку «New project», чтобы создать новый проект. У нас появится следующий интерфейс.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less3/less3__01.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"Здесь мы можем выбрать расположение, название проекта. И, пожалуй, самое интересное — к проекту мы можем применить шаблоны. Важно: шаблоны применяются на стадии создания проекта, если не применить их на данном шаге — вернуться назад не выйдет и потребуется создавать новый проект.\"},{\"block\":\"p\",\"content\":\"В качестве примера мы создадим проект в 2D пространстве с названием «ExampleApp» и сохраним его в какую-нибудь папку. Рекомендую создать удобную иерархию для вас, создайте папку «UnityProjects» и сохраняйте все проекты туда. Так вам будет удобно возвращаться к разрабатываемым вами проектам.\"},{\"block\":\"p\",\"content\":\"По центру выбираем «2D Core». Справа даем название проекта под надписью «Project name», по умолчанию название проекта — «My project». Внизу, под надписью «Location» выбираем путь до папки, для этого нажимаем на иконку папки справа.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less3/less3__02.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"Отлично! Мы создали свой первый проект. По умолчанию у вас отобразится следующий интерфейс. В настройках можно включить светлую тему, можете посмотреть в интернете инструкцию.\"},{\"block\":\"h2\",\"content\":\"Интерфейс Unity\"},{\"block\":\"p\",\"content\":\"Давайте рассмотрим интерфейс и разберем каждую его деталь. Итак, разделим интерфейс на 4 элемента:\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less3/less3__03.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"ol\",\"items\":[\"Это вкладка «Hierarchy» или же Иерархия. Она отвечает за объекты на текущей сцене. С помощью данной вкладки можно отслеживать количество объектов на сцене, выбирать нужный.\",\"Вкладка «Project» отвечает за папку проекта. Если вы откроете папку проекта, вы увидите папку «Assets». Именно папка «Assets» отображается на вкладке «Project».\",\"Вкладка «Scene» отвечает за отображение сцены. С помощью данной вкладки можно передвигаться по сцене.\",\"Вкладка «Inspector» или же Инспектор. С его помощью можно узнать подробнее про выбранный объект. Если ничего не выбрать — будет отображаться пустая вкладка как в моем случае. Вкладка Инспектор отображает компоненты объекта, с которыми мы познакомимся позже.\"]},{\"block\":\"p\",\"content\":\"Сразу стоит сказать — интерфейс мы можете подстраивать под свои задачи как угодно.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less3/less3__04.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"Если вы посмотрите на верхнюю часть вкладки, вы можете увидеть несколько кнопок: «Scene» и «Game». Если нажать на кнопку «Game» — на месте вкладки «Scene» отобразится вкладка «Game».\"},{\"block\":\"p\",\"content\":\"Есть еще 2 вкладки, о которых мы не упомянули, потому что они скрыты. Для того, чтобы их открыть, нужно нажать на их название. Данные вкладки появляются на месте предыдущей вкладки, которая была открыта. К примеру, была открыта вкладка «Scene», если мы нажмем на вкладку «Game», то на месте «Scene» отобразится вкладка «Game».\"},{\"block\":\"p\",\"content\":\"Еще 2 вкладки:\"},{\"block\":\"ol\",\"items\":[\"Вкладка «Game» в поле номер 3. Вкладка «Game» отличается от вкладки «Scene» тем, что по вкладке «Scene» мы можем передвигаться свободно. А вкладка «Game» показывает, как будет выглядеть игра для пользователя. Иными словами, вкладка «Scene» — это свободный режим передвижения, а вкладка «Game» — результат наших настроек в игре.\",\"Вкладка «Console» или Консоль в поле номер 2. Здесь будут выводиться результаты работы скриптов. Обычно Консоль требуется для дебага кода.\"]},{\"block\":\"quote\",\"content\":\"«Дебаг кода» — устранение ошибок в коде.\"}]},{\"slug\":\"4\",\"title\":\"4. Создадим проект. Запустим на Android\",\"short\":\"Создадим проект. Запустим на Android\",\"content\":[{\"block\":\"p\",\"content\":\"Давайте разработаем простой проект, из которого создадим сборку игры для Android. Предлагаю сделать простой проект, при запуске которого мы будем видеть красный цвет. Мы еще успеем разработать интересные игры, сейчас проверим, что все правильно работает.\"},{\"block\":\"p\",\"content\":\"Выберите «Main Camera» или Камера слева в «Hierarchy» или Иерархии. После того, как мы выберем Камеру, справа появятся ее компоненты. Поговорим о них подробнее.\"},{\"block\":\"quote\",\"content\":\"Компонент — функциональная часть каждого игрового объекта.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less4/less4__01.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"Поговорим подробнее про окно Инспектора («Inspector»). В самом вверху находится название объекта: «Main Camera», объекту мы можем дать любое название. Слева от названия есть белая галочка, она нужна для того, чтобы выключать объект. Это бывает необходимо, когда объект скрывается на время.\"},{\"block\":\"p\",\"content\":\"Внизу от названия есть поле «Tag» или тег. Сейчас тег объекта: «Main Camera». Теги нужны для того, чтобы искать определенный объект по его тегу. Справа от тега есть поле «Layer» или слой. Сейчас слой объекта: «Default». Слой нужен для того, чтобы большое количество объектов приписать к одной логике. К примеру, с помощью слоев можно избавиться от проблемы бесконечных прыжков. О них мы поговорим при создании своего 2D платформера.\"},{\"block\":\"p\",\"content\":\"После описанных мною полей идут компоненты объекта. Мы можем подключать компоненты, внизу есть кнопка «Add Component».\"},{\"block\":\"h2\",\"content\":\"Изменяем цвет фона\"},{\"block\":\"p\",\"content\":\"Для того, чтобы изменить цвет заднего фона, мы можем перейти к компоненту «Camera», к полю «Background».\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less4/less4__02.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"Для того, чтобы изменить цвет — нужно нажать на синий цвет справа от поля «Background».\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less4/less4__03.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"Появится палитра выбора цвета. Поговорим подробнее про цвета. Для того, чтобы выбрать красный цвет, мы должны сделать следующее: переводим курсор на круг, в котором находится квадрат, нажимаем курсор на белый маленький кружок и переводим его в район красного цвета. Таким образом мы выбрали красный цвет.\"},{\"block\":\"p\",\"content\":\"Теперь нам нужно изменить насыщенность цвета. Для этого уже внутри квадрата белый кружок мы должны перевести в правый верхний угол.\"},{\"block\":\"h2\",\"content\":\"Выбираем цвет\"},{\"block\":\"p\",\"content\":\"Давайте разберёмся, как описывают цвет. Например, я говорю «красный» — но какой именно красный? Ведь существует разные варианты цветов красного цвета. Тоже самое и про другие цвета.\"},{\"block\":\"p\",\"content\":\"Есть 4 варианта, как распространять информацию о цвете:\"},{\"block\":\"ul\",\"items\":[\"RGB 0-255: цвет задается с помощью трех ползунков: красного, зеленого и синего цвета, каждый из которых принимает значение от нуля до 255. Сочетание цветов создают новые спектры цветов.\",\"RGB 0-1.0: такой же вариант RGB, но вместо ограничения в 255, используется ограничение в 1.0 и цвет задается с помощью десятичной дроби (0.5, 0.32, 0.1).\",\"HSV: цвет задается с помощью трех ползунков: первый — тон (Hue), то есть положение цвета на цветовом круге, второй — насыщенность (Saturation), третий — яркость (Value)\",\"HEX: как по мне, самый удобный вариант. Цвет задается через решетку, а далее идут три пары символов в шестнадцатеричной системе счисления: красный, зеленый и синий, каждая пара — значение от 00 до FF.\"]},{\"block\":\"quote\",\"content\":\"Шестнадцатиричная система счисления — позиционная система счисления по основанию 16. В качестве цифр этой системы счисления используются цифры от 0 до 9 и латинские буквы от A до F.\"},{\"block\":\"p\",\"content\":\"Поговорим подробнее о том, каким образом цвета задаются в каждом из вариантов.\"},{\"block\":\"p\",\"content\":\"Красный:\"},{\"block\":\"ol\",\"items\":[\"(255,0,0)\",\"(1.0,0,0)\",\"(0, 100, 100)\",\"#ff0000\"]},{\"block\":\"p\",\"content\":\"Зеленый:\"},{\"block\":\"ol\",\"items\":[\"(0,255,0)\",\"(0,1.0,0)\",\"(120,100,100)\",\"#00ff00\"]},{\"block\":\"p\",\"content\":\"Синий:\"},{\"block\":\"ol\",\"items\":[\"(0,0,255)\",\"(0,0,1.0)\",\"(240,100,100)\",\"#0000ff\"]},{\"block\":\"p\",\"content\":\"Каждый из цветов задается определенным кодом. Далее по курсу я буду использовать вариант цветов HEX или RGB 0-1.0, потому что они самые удобные. Для того, чтобы изменить цвет через HEX параметр, нужно открыть палитру цветов и в нижней части изменить поле «Hexadecimal». Именно данный параметр отвечает за HEX-цвет.\"},{\"block\":\"h2\",\"content\":\"Альфа-канал\"},{\"block\":\"p\",\"content\":\"Еще у цветов имеется такая настройка, как альфа-канал.\"},{\"block\":\"quote\",\"content\":\"Альфа-канал — комбинирование изображения с фоном с целью создания эффекта частичной прозрачности.\"},{\"block\":\"p\",\"content\":\"Альфа-канал может быть изменен с помощью поля с названием «A».\"},{\"block\":\"h2\",\"content\":\"Собираем проект под Android\"},{\"block\":\"p\",\"content\":\"Отлично, мы изменили цвет фона. Да, игрой сейчас это нельзя назвать, но нам нужно разобраться, как запустить игру на Android.\"},{\"block\":\"p\",\"content\":\"Перейдем к сборке игры под Android. Перейдите в верхнюю часть экрана, найдите пункт «File», там будет пункт «Build Settings».\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less4/less4__04.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"У меня операционная система macOS, поэтому интерфейс может немного отличаться. На Windows или Linux данный пункт находится в том же месте.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less4/less4__05.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"После нажатия у нас появится окно «Build Settings». Отсюда мы будем управлять сборкой игры. Давайте подробнее поговорим о том, что такое сборка игры.\"},{\"block\":\"p\",\"content\":\"Сейчас мы редактируем файлы игры. Мы находимся в проекте, в котором разрабатываем игру. Из Unity мы можем управлять файлами игры, добавлять обновления для игры и собирать проект.\"},{\"block\":\"p\",\"content\":\"Для того, чтобы запустить проект на определенной платформе, требуется создать сборку игры под конкретную платформу. Существует разные варианты сборки игры: для Android, Windows, macOS, Linux, iOS и даже WebGL. В рамках данного курса мы будем создавать сборки игры под Android и Windows.\"},{\"block\":\"p\",\"content\":\"После сборки проекта под Android у нас появится файл «<название>.apk» — это и будет файлом скачивания нашей игры. Из проекта мы создали скачиваемый файл или же сделали сборку проекта под платформу Android.\"},{\"block\":\"p\",\"content\":\"В случае с платформой Windows конечный файл у нас будет представлен в папке, а запускаемый файл будет «<название>.exe».\"},{\"block\":\"p\",\"content\":\"Сейчас мы делаем сборку игры под Android, поэтому слева в пункте «Platform» нам нужно выбрать пункт «Android». После нажатия справа внизу у нас вместо кнопок «Build» и «Build And Run» появится кнопка «Switch Platform». Нам нужно нажать на нее, чтобы сменить платформу сборки. Этот процесс занимает некоторое время, обычно меньше 5 минут.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less4/less4__06.jpg\",\"alt\":\"Открытый Unity Hub\"},{\"block\":\"p\",\"content\":\"Возможно после сборки в консоле появятся ошибки. Данные ошибки не повлияют на сборку проекта, мы можем проигнорировать их.\"},{\"block\":\"p\",\"content\":\"После того, как мы сменили платформу, нам нужно сделать сборку игры. Для этого нажимаем справа внизу на кнопку «Build», нам нужно будет выбрать папку, куда сохранить файл. Обычно я сохраняю в корне проекта (в папке с названием «ExampleApp»). Еще нам нужно дать название проекту, мы можем выбрать любое, лично я назвал «android». В названии указывать расширение не требуется, достаточно просто написать название файла без «.apk».\"},{\"block\":\"p\",\"content\":\"После сборки в корне проекта у нас появится файл «android.apk». Теперь мы можем передать данный файл на телефон на Android, нажать по файлу и установить нашу игру. После запуска мы увидим красный цвет.\"}]},{\"slug\":\"5\",\"title\":\"5. Разработка 2д платформера. Подготовка\",\"short\":\"Разработка 2д платформера. Подготовка\",\"content\":[{\"block\":\"p\",\"content\":\"Мы установили игровой движок Unity, мы познакомились с интерфейсом движка и даже создали свой первый проект. Мы готовы перейти к чему-то более серьезному.\"},{\"block\":\"p\",\"content\":\"Очень часто первым проектом при изучении Unity является 2д платформер. Все дело в простоте разработки такой игры. Но, вместе с тем, вы сможете познакомиться с основой программирования и разработки игр на разные платформы.\"},{\"block\":\"h2\",\"content\":\"Создаем проект\"},{\"block\":\"p\",\"content\":\"Перейдем к созданию проекта. Для этого запустим Unity Hub. На главной странице нажмем на кнопку «New project» в правом верхнем углу.\"},{\"block\":\"p\",\"content\":\"После чего нам нужно выбрать «2D Core» посередине. А справа в поле «Project name» дать название игре. Я назову «Platformer». И ниже, в поле «Location» выбрать папку для проекта. Пускай папка проекта будет та, которую мы уже создали: «UnityProjects».\"},{\"block\":\"h2\",\"content\":\"Работа со сценами\"},{\"block\":\"p\",\"content\":\"Я создаю проект по своему стандартному шаблону. Первое, что я делаю: меняю название стандартной сцены на «Game» и создаю новую сцену «Menu».\"},{\"block\":\"p\",\"content\":\"Все сцены находятся в папке «/Assets/Scene/» — это расположение по умолчанию. Внутри будет лежать сцена, выглядит она вот так:\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less5/less5__01.jpg\",\"alt\":\"Игровое пространство Unity\"},{\"block\":\"p\",\"content\":\"Мы можем нажать правой кнопкой и выбрать пункт «Rename», далее даем новое название для сцены, как я уже и сказал: «Game».\"},{\"block\":\"p\",\"content\":\"Следующим шагом нужно создать новую сцену. Для этого в окне «Project» я кликаю правой кнопкой мыши. Появляется контекстное меню, я выбираю пункт «Create», в нем пункт «Scene».\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less5/less5__02.jpg\",\"alt\":\"Игровое пространство Unity\"},{\"block\":\"p\",\"content\":\"После создания сцены нужно сразу дать название новой сцене, либо изменить название, как показано выше. Название для новой сцены: «Menu».\"},{\"block\":\"h2\",\"content\":\"Добавление текстур\"},{\"block\":\"p\",\"content\":\"Переходим к добавлению текстур. Я не умею рисовать, поэтому я буду использовать стандартный пакет графики.\"},{\"block\":\"p\",\"content\":\"[Скачать стандартный пакет графики](/courses/unity-first-game/unity_1.zip)\"},{\"block\":\"p\",\"content\":\"Этот пакет графики я создал сам. В нем находятся файлы в формате «.png» — это и есть будущая графика для игры: круг, квадрат и шестиугольник. Создадим из этого легендарную игру!\"},{\"block\":\"p\",\"content\":\"Перейдем к импорту графики в игру. Переходим в корень проекта, для этого в окне «Project» в верхней строке с «Assets > Scenes» нажимаем на «Assets». Так мы перейдем в корень проекта.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less5/less5__03.jpg\",\"alt\":\"Игровое пространство Unity\"},{\"block\":\"p\",\"content\":\"В корне нужно создать папку с названием «Texture». Для этого по пустой области в окне «Project» кликаем правой кнопкой маши. В появившимся меню выбираем пункт «Create», далее выбираем «Folder».\"},{\"block\":\"p\",\"content\":\"После того, как создали папку, даем ей новое название. Правой кнопкой мыши по папке, выбираем пункт «Rename» и даем название: «Texture».\"},{\"block\":\"h2\",\"content\":\"Импорт графики в игру\"},{\"block\":\"p\",\"content\":\"Теперь переходим к импорту графики. Мы можем сделать это двумя способами.\"},{\"block\":\"p\",\"content\":\"Первый способ: открываем проводник, в нем выделяем файлы из папки «unity_1.zip», не отпуская курсор переключаемся на проект в Unity, переводим курсор на окно «Project» и отпускаем.\"},{\"block\":\"p\",\"content\":\"Второй способ: открываем проект в проводнике, открываем папку «Texture» и в эту папку обычным копированием переносим нашу графику.\"},{\"block\":\"h2\",\"content\":\"Завершение настройки\"},{\"block\":\"p\",\"content\":\"Мы почти что завершили подготовительный процесс. Осталось создать папку «Scripts», пока что оставляем папку пустой.\"},{\"block\":\"p\",\"content\":\"И еще я хочу переименовать объект «Main Camera» в «camera». Делать это необязательно.\"},{\"block\":\"p\",\"content\":\"Для того, чтобы переименовать: переходим в окно «Hierarchy», находим объект с названием «Main Camera», наводим на него курсор, кликаем правой кнопкой мыши и в меню выбираем «Rename», далее даем новое название «camera».\"}]},{\"slug\":\"6\",\"title\":\"6. Работа над локацией\",\"short\":\"Работа над локацией\",\"content\":[{\"block\":\"p\",\"content\":\"В прошлом уроке мы настроили первый игровой проект. В рамках данного урока нам предстоит поработать над внешним видом игры.\"},{\"block\":\"h2\",\"content\":\"Меняем цвет заднего фона\"},{\"block\":\"p\",\"content\":\"Первое, что я хочу сделать — изменить цвет заднего фона. Сейчас цвет фона: #314D79, я же хочу поставить: #5E6EAE.\"},{\"block\":\"p\",\"content\":\"Для того, чтобы изменить цвет фона: выбираем объект «camera» в окне «Hierarchy», справа в «Inspector» у компонента «Camera» меняю поле «Background».\"},{\"block\":\"h2\",\"content\":\"Добавляем игрока\"},{\"block\":\"p\",\"content\":\"Теперь добавим игрока. Это будет наш первый объект на сцене. Для этого я зайду в папку «Texture», выберу круг и перетяну его в окно «Scene» или «Hierarchy».\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less6/less6__01.jpg\",\"alt\":\"Игровая сцена Unity\"},{\"block\":\"p\",\"content\":\"После перетягивания в окне «Scene» появится белый круг. Давайте дадим ему название «Player». Изменим тег на «Player» в окне «Inspector». Еще изменим его цвет заливки на #67D7E5. Для этого в компоненте «Sprite Renderer» измените поле «Color». В том же компоненте измените поле «Order in Layer» на значение «10».\"},{\"block\":\"quote\",\"content\":\"«Order in Layer» — позволяет контролировать порядок рендеринга 2D-объектов независимо от их физического расстояния от камеры.\"},{\"block\":\"h2\",\"content\":\"Добавим компоненты на игрока\"},{\"block\":\"p\",\"content\":\"Отлично. Мы добавили игрока на сцену. Теперь нам нужно добавить компоненты для игрока. Нам нужно 2 компонента: физика и границы объекта.\"},{\"block\":\"p\",\"content\":\"Для добавления компонента выберем игрока. В окне «Inspector» в нижней части нажмем на кнопку «Add Component». Первый компонент, который мы добавим: «Rigidbody 2D».\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less6/less6__02.jpg\",\"alt\":\"Игровой компонент Unity\"},{\"block\":\"quote\",\"content\":\"Компонент «Rigidbody 2D» — основной компонент, подключающий физическое поведение для объекта в двухмерном пространстве.\"},{\"block\":\"p\",\"content\":\"У компонента Rigidbody 2D мы оставим все настройки по умолчанию, кроме одной. У компонента Rigidbody 2D нажмите на поле «Constraints». В появившимся поле поставьте галочку напротив поля «Freeze Rotation».\"},{\"block\":\"p\",\"content\":\"Это нужно для того, чтобы игрок всегда находился горизонтально и не «падал».\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less6/less6__03.jpg\",\"alt\":\"Игровой компонент Unity\"},{\"block\":\"p\",\"content\":\"Следующий компонент, который мы добавим: «Circle Collider 2D». Без данного компонента игрок будет просто падать.\"},{\"block\":\"quote\",\"content\":\"Компонент «Circle Collider 2D» — коллайдер в форме окружности, который взаимодействует с системой 2D-физики для приблизительного столкновения.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less6/less6__04.jpg\",\"alt\":\"Игровой компонент Unity\"},{\"block\":\"p\",\"content\":\"Данный компонент не требуется дополнительно настраивать, потому что границы объекта соответствуют границам графики.\"},{\"block\":\"h2\",\"content\":\"Запуск игры\"},{\"block\":\"p\",\"content\":\"Давайте проверим настройку нашей игры и запустим ее. Для того, чтобы запустить игру, нужно в верхней части экрана нажать на кнопку «Play». Она находится слева.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less6/less6__05.jpg\",\"alt\":\"Игровой компонент Unity\"},{\"block\":\"p\",\"content\":\"После нажатия на кнопку появится окно Unity, в котором произойдет небольшая настройка. После чего автоматически откроется окно «Game».\"},{\"block\":\"p\",\"content\":\"Сама игра работает сейчас таким образом: после запуска наш игрок медленно опускается вниз.\"},{\"block\":\"p\",\"content\":\"Все работает правильно. Единственное, что нам нужно добавить: платформы, по которым игрок будет перемещаться.\"},{\"block\":\"h2\",\"content\":\"Добавляем платформы для перемещения\"},{\"block\":\"p\",\"content\":\"Добавим платформы. Переходим в папку «Texture». Выделяем квадрат и перетягиваем на сцену. Даем название объекту: «Platform». И обязательно сохраняемся. Для сохранения нажимаем комбинацию клавиш: ‘Ctrl’ + ’S’ на Windows, ‘command’ + ’S’ на macOS.\"},{\"block\":\"p\",\"content\":\"После добавления платформы у нас появится белый квадрат по центру. Изменим его координаты и размер. Для этого выделим платформу. В окне «Inspector» изменим компонент «Transform». Поле «Position» координату «Y» изменим на «-3». Поле «Scale» координату «X» изменим на «6», а координату «Y» на «0.5».\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less6/less6__06.jpg\",\"alt\":\"Игровой компонент Unity\"},{\"block\":\"p\",\"content\":\"Мы изменили координаты и размер платформы. Теперь она выглядит таким образом.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less6/less6__07.jpg\",\"alt\":\"Игровая сцена Unity\"},{\"block\":\"p\",\"content\":\"К платформе требуется добавить компонент «Box Collider 2D». Дополнительно настраивать компонент не требуется, он автоматически подстроился по размерам.\"},{\"block\":\"quote\",\"content\":\"Компонент «Box Collider 2D» — коллайдер в форме квадрата, который взаимодействует с системой 2D-физики для приблизительного столкновения.\"},{\"block\":\"h2\",\"content\":\"Добавляем врага и еду\"},{\"block\":\"p\",\"content\":\"Осталось добавить 2 объекта: врага и еду. Два этих объекта будут представлять собой шестиугольник.\"},{\"block\":\"p\",\"content\":\"Добавляем на сцену два шестиугольника из папки «Texture». Мы можем либо два раза перенести шестиугольник на сцену, либо скопировать уже созданный шестиугольник.\"},{\"block\":\"p\",\"content\":\"Первый шестиугольник: еда. Изменяем цвет: #8BFA81, название: «Eat», расположение по «X»: «-5».\"},{\"block\":\"p\",\"content\":\"Второй шестиугольник: враг. Изменяем цвет: #F16E6E, название: «Enemy», расположение по «X»: «5».\"},{\"block\":\"p\",\"content\":\"Добавим на каждый шестиугольник компонент «Circle Collider 2D». Настроим компоненты следующим образом: для объекта «Eat» изменим у компонента «Circle Collider 2D» поле «Radius» на «1.5». А у объекта «Enemy» изменим на «1».\"},{\"block\":\"p\",\"content\":\"Еще для объекта «Enemy» нужно добавить компонент «Rigidbody 2D».\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less6/less6__08.jpg\",\"alt\":\"Игровая сцена Unity\"},{\"block\":\"h2\",\"content\":\"Проверим работу игры\"},{\"block\":\"p\",\"content\":\"Запустим игру. После запуска игрок и враг упадут на платформу, а объект еды останется на сцене без изменений, потому что на объект «Eat» не действует физика, потому что мы не добавили компонент «Rigidbody 2D».\"}]},{\"slug\":\"7\",\"title\":\"7. Программируем на C#\",\"short\":\"Программируем на C#\",\"content\":[{\"block\":\"p\",\"content\":\"В прошлом уроке мы разработали прототип игры. Добавили коллайдеры и физику для объектов. Добавили главного игрока, врага и еду. Теперь перед нами стоит задача написать скрипты для игры.\"},{\"block\":\"h2\",\"content\":\"Создаем скрипты\"},{\"block\":\"p\",\"content\":\"Переходим к созданию скриптов. Для того, чтобы добавить скрипты, нам нужно перейти в папку «Assets/Scripts». Далее, в окне «Project» нажимаем правой кнопкой мыши и выбираем пункт «Create», почти в самом верху будет пункт «C# Script». Выбираем данный пункт.\"},{\"block\":\"p\",\"content\":\"После создания скрипта у нас появится файл C#, которому нам нужно дать название. Важно: нельзя просто так переименовывать файл скрипта, потому что на названии завязано содержимое не только одного скрипта, но и всех остальных.\"},{\"block\":\"p\",\"content\":\"Создаем скрипт «PlayerMovable». Здесь будет находиться обработчик передвижения игрока. Для начала создадим обработчик для компьютера, после добавим поддержку мобильного управления.\"},{\"block\":\"h2\",\"content\":\"Разбираем скрипт\"},{\"block\":\"p\",\"content\":\"По умолчанию файл скрипта имеет следующую структуру. Разберем подробнее.\"},{\"block\":\"code\",\"language\":\"C#\",\"content\":\"using System.Collections;\\nusing System.Collections.Generic;\\nusing UnityEngine;\\n\\npublic class PlayerMovable : MonoBehaviour\\n{\\n    // Start is called before the first frame update\\n    void Start()\\n    {\\n\\n    }\\n\\n    // Update is called once per frame\\n    void Update()\\n    {\\n\\n    }\\n}\"},{\"block\":\"p\",\"content\":\"Скрипты для игрового движка Unity пишутся на языке программирования C#. Язык программирования C# подходит для разных задач, также на нем создаются скрипты для игрового движка Unity.\"},{\"block\":\"p\",\"content\":\"В конце почти каждой строчки ставится знак «;». Он ставится после определения библиотек, полей, и строк кода внутри методов.\"},{\"block\":\"h2\",\"content\":\"Библиотеки\"},{\"block\":\"p\",\"content\":\"Первые 3 строчки: подключаемые библиотеки, они подключаются в любом скрипте для игрового движка Unity.\"},{\"block\":\"quote\",\"content\":\"Библиотека — сборник подпрограмм или объектов, используемых для разработки программного обеспечения.\"},{\"block\":\"h2\",\"content\":\"Класс\"},{\"block\":\"p\",\"content\":\"Далее — описывается класс следующей структурой:\"},{\"block\":\"p\",\"content\":\"`<публичность> class <название_скрипта> : MonoBehaviour { … }`\"},{\"block\":\"p\",\"content\":\"Нетрудно догадаться, что название «class» и определение «MonoBehaviour» тоже является обязательным в скриптах.\"},{\"block\":\"quote\",\"content\":\"Public — это ключевое слово, которое используется в качестве модификатора доступа для методов и переменных.\"},{\"block\":\"p\",\"content\":\"Публичность определяет доступ к нашему классу с «внешнего мира», иначе говоря, с других классов. Наш класс может быть публичным, может быть приватным. Если говорить иначе, если наш класс публичный — мы можем к нему обращаться из других скриптов. Если закрытый — то обращение невозможно.\"},{\"block\":\"p\",\"content\":\"После класса стоит фигурная скобка: «{». В конце скрипта данная фигурная скобка закрывается: «}». Данные фигурные скобки «говорят», что они относятся к классу. Любой класс должен содержать фигурные скобки по синтаксису C#. Данные скобки обозначают, где начинается наш класс и где он заканчивается.\"},{\"block\":\"p\",\"content\":\"Фигурные скобки очень полезные и удобные. Фигурные скобки используются у классов, методов и некоторых других структур, к примеру, enum’ов.\"},{\"block\":\"h2\",\"content\":\"Комментарии\"},{\"block\":\"p\",\"content\":\"Далее, мы видим такой синтаксис: «// Start is called before the first frame update». Такой синтаксис обозначает комментарий в коде.\"},{\"block\":\"quote\",\"content\":\"Комментарий — пояснения к исходному тексту программы, находящиеся непосредственно внутри комментируемого кода.\"},{\"block\":\"p\",\"content\":\"Комментарий может начинаться с «//», с таким синтаксисом комментарий будет «работать» только для одной строки.\"},{\"block\":\"p\",\"content\":\"А если написать такой синтаксис: «/* Comment */», то комментарий имеет начало: «/*» и имеет конец: «*/». С таким синтаксисом комментарий не будет ограничен той строкой, с которой он начинается.\"},{\"block\":\"p\",\"content\":\"Другими словами, если мы начнем писать большой текст с комментарием типа «//», то двойной слэш нужно будет ставить у каждой строки. А если использовать «/* */», то достаточно будет выделить начало и конец комментария.\"},{\"block\":\"code\",\"language\":\"C#\",\"content\":\"// Пример текста в одну строку\\n\\n/*\\nПример большого текста,\\nкоторый разделен на разные строки,\\nчтобы показать,\\nкак работает пример комментария */\"},{\"block\":\"h2\",\"content\":\"Методы\"},{\"block\":\"p\",\"content\":\"Перейдем к методам нашего класса. Метод начинается с ключевого слова «void» и имеет следующий синтаксис:\"},{\"block\":\"p\",\"content\":\"`<публичность> void <название_метода> (<поля>) { … }`\"},{\"block\":\"quote\",\"content\":\"Метод — это функция или процедура, принадлежащая какому-то классу или объекту.\"},{\"block\":\"p\",\"content\":\"В примере кода выше мы видим, что наш метод начинается сразу с ключевого слова «void». Если мы не указываем тип публичности: public, private, то автоматически это считается за private. Иными словами, получить доступ к методам из других скриптов у нас не получится. Чтобы получить доступ к методам из других скриптом, нам потребуется перед «void» поставить «public».\"},{\"block\":\"p\",\"content\":\"После названия метода идет следующий синтаксис: «(<поля>)». В круглых скобках метод может принимать различные значения. Мы познакомимся с логикой на практике.\"},{\"block\":\"p\",\"content\":\"Внутри фигурных скобок «{ … }» ставится код. Код, который находится между фигурных скобок называется «телом метода».\"},{\"block\":\"quote\",\"content\":\"«Тело» метода — это блок, который представляет собой набор описаний переменных и операторов, заключенных в фигурные скобки.\"},{\"block\":\"p\",\"content\":\"Мы используем методы для вызова определенного кода в нужный момент времени. Методы разбивают логику на понятные части, а Start() и Update() Unity вызывает сама — без них скрипт ничего делать не будет.\"},{\"block\":\"h2\",\"content\":\"Ответы на вопросы\"},{\"block\":\"ol\",\"items\":[\"Зачем нужны библиотеки в скрипте? Библиотеки содержат подключаемые модули и различные зависимости. В подключаемых библиотеках описывается логика скриптов, которые мы будем писать.\"]},{\"block\":\"ol\",\"items\":[\"Зачем нужен класс в скрипте? По синтаксису C# любой файл должен представлять собой определенный класс. Класс можно представить собой сущность, к примеру, как человек. Класс будет содержать нашу логику. В случае со скриптом «PlayerMovable» класс будет описывать движение игрока.\"]},{\"block\":\"ol\",\"items\":[\"Зачем нужны методы в скрипте? Методы позволяют вызвать нужный код в нужный момент времени. Мы сами определяем, в какой именно момент времени код должен быть вызван или должен вызываться.\"]},{\"block\":\"ol\",\"items\":[\"Можно ли обойтись без подключения библиотек? Нет. Мы должны подключить библиотеки по синтаксису C#.\"]},{\"block\":\"ol\",\"items\":[\"Можно ли обойтись без класса? Нет. Любой файл скрипта должен иметь класс внутри себя. Название файла скрипта и класса должны строго соответствовать. Если нарушить логику — игра не будет запускаться.\"]},{\"block\":\"ol\",\"items\":[\"В одном файле скрипта должен быть один метод? Нет, не обязательно. Методов в классе может быть сколько угодно. Классов в одном файле C# тоже может быть несколько, но для Unity действует важное правило: класс-наследник MonoBehaviour, который вы вешаете на объект, должен называться так же, как файл. Иначе Unity не свяжет скрипт с компонентом.\"]},{\"block\":\"ol\",\"items\":[\"Если допустить ошибку, то произойдет? Если ошибка критическая — ошибка будет отображена в консоли, а игра не будет запускаться. В некоторых случаях ошибка, по началу, может не повлиять на работу игры, но может помешать при определенном действии, которое вызовет ошибку.\"]},{\"block\":\"h2\",\"content\":\"Поля\"},{\"block\":\"p\",\"content\":\"Мы разобрали основы кода: структуру файла, библиотеки и методы. Теперь нам требуется разобраться с полями или переменными: что это такое, какой имеют функционал.\"},{\"block\":\"quote\",\"content\":\"Поля, переменные — поименованная, либо адресуемая иным способом область памяти, адрес которой можно использовать для осуществления доступа к данным.\"},{\"block\":\"p\",\"content\":\"В некоторых случаях используют название «поле», в некоторых «переменная». Фактически — это одно и тоже название. Но, конечно же, они имеют небольшие отличия. Поля обозначаются внутри класса, переменные — внутри метода. Но отличать это необязательно.\"},{\"block\":\"h2\",\"content\":\"Типы данных\"},{\"block\":\"p\",\"content\":\"Теперь нам нужно ознакомиться с синтаксисом и с типами данных полей. Заведем следующую структуру.\"},{\"block\":\"code\",\"language\":\"C#\",\"content\":\"using System.Collections;\\nusing System.Collections.Generic;\\nusing UnityEngine;\\n\\npublic class PlayerMovable : MonoBehaviour\\n{\\n    private int count = 0;\\n    private float speed = 0f;\\n    private string name = \\\"\\\";\\n    private bool move = false;\\n}\"},{\"block\":\"p\",\"content\":\"Я убрал «тело» класса. Вместо стандартной структуры я добавил 4 поля.\"},{\"block\":\"p\",\"content\":\"Поля имеют следующую структуру:\"},{\"block\":\"p\",\"content\":\"`<публичность> <тип_данных> <название_поля> = <значение>;`\"},{\"block\":\"p\",\"content\":\"Каждое это поле начинается с ключевого слова «private», что означает закрытость поля. То есть, получить доступ к полю из других классов нельзя.\"},{\"block\":\"p\",\"content\":\"Если не написать «private», а начать сразу с типа данных, данное поле, по умолчанию, будет считаться как «private». Но в рамках хорошего кода лучше явно обозначать закрытость поля через слово «private».\"},{\"block\":\"p\",\"content\":\"Дальше идут типы данных. Всего существует несколько основных типов данных:\"},{\"block\":\"ul\",\"items\":[\"string\",\"int\",\"float\",\"bool\",\"double\",\"object\"]},{\"block\":\"h2\",\"content\":\"Подробнее о каждом типе данных\"},{\"block\":\"ul\",\"items\":[\"Тип данных «string»: строковое значение, записывается через синтаксис: \\\"<текст>\\\". Обычно используется для названий.\"]},{\"block\":\"ul\",\"items\":[\"Тип данных «int»: целое числовое значение. Не хранит дробные значения (1.5, 3.2). Записывается через синтаксис: <значение>.\"]},{\"block\":\"ul\",\"items\":[\"Тип данных «float»: дробное числовое значение. Хранит все значения через «плавающую» точку. Записывается через синтаксис: <значение>f. Буква «f» в конце обозначает принадлежность к дробному значению.\"]},{\"block\":\"ul\",\"items\":[\"Тип данных «bool»: проверяет истинность высказывания. Хранит только 2 значения: «true» или «false». Используется для «переключатель» или для проверки истинности высказывания.\"]},{\"block\":\"ul\",\"items\":[\"Тип данных «double»: то же самое, что и float, но с большим диапазоном значений. Записывается без суффикса: <значение>.\"]},{\"block\":\"ul\",\"items\":[\"Тип данных «object»: базовый тип, от которого наследуются все остальные. В такое поле можно положить значение любого типа. Значение по умолчанию — null, то есть «ничего», поэтому перед использованием полю нужно что-то присвоить.\"]},{\"block\":\"h2\",\"content\":\"Значения по умолчанию\"},{\"block\":\"p\",\"content\":\"Я задал значения полям, которые являются значениями по умолчанию. Если не задать значение полям, они будут иметь значения по умолчанию.\"},{\"block\":\"p\",\"content\":\"Для того, чтобы задать значение полю, требуется использовать следующий синтаксис: «= <значение>». Так мы сможем задать, к примеру, переменной типа int значение 3.\"},{\"block\":\"p\",\"content\":\"`private int count = 3;`\"},{\"block\":\"p\",\"content\":\"Укажем все значения по умолчанию:\"},{\"block\":\"ul\",\"items\":[\"числовые типы данных: 0 или 0f\",\"строковые типы данных: null, то есть «ничего» (пустую строку нужно задавать явно)\",\"bool: false (ложь)\"]}]},{\"slug\":\"8\",\"title\":\"8. Работаем над логикой игры\",\"short\":\"Работаем над логикой игры\",\"content\":[{\"block\":\"p\",\"content\":\"В этом уроке мы поработаем над логикой игры. Перейдем к программированию на C#. Создадим несколько игровых скриптов, которые будут описывать логику работы игры.\"},{\"block\":\"code\",\"language\":\"C#\",\"content\":\"using System.Collections;\\nusing System.Collections.Generic;\\nusing UnityEngine;\\n\\npublic class PlayerMovable : MonoBehaviour\\n{\\n    [SerializeField] private Transform groundPoint;\\n    [SerializeField] private LayerMask groundLayer;\\n\\n    private Rigidbody2D rb;\\n\\n    private float speed = 7f;\\n    private float jumpForce = 5f;\\n\\n    private float moveInput;\\n    private float flipValue;\\n}\"},{\"block\":\"h2\",\"content\":\"Создадим поля в «PlayerMovable»\"},{\"block\":\"p\",\"content\":\"`[SerializeField] private`\"},{\"block\":\"p\",\"content\":\"Данный блок кода отвечает за возможность добавить ссылку на поле в Инспекторе. Отличия от модификатора доступа «public» в том, что модификатор доступа разрешает доступ к полю из других скриптов и доступ из Инспектора, а SerializeField разрешает только доступ из Инспектора.\"},{\"block\":\"p\",\"content\":\"Разберем каждое поле отдельно:\"},{\"block\":\"ul\",\"items\":[\"groundPoint: это точка, которая будет отвечать за касание с землей.\",\"groundLayer: это слой, который будет отвечать за «землю».\",\"rb: ссылка на физику объекта.\",\"speed: задаем скорость игрока.\",\"jumpForce: задаем силу прыжка.\",\"moveInput: ссылка на направление движения.\",\"flipValue: параметр, отвечающий за поворот игрока.\"]},{\"block\":\"h2\",\"content\":\"Добавляем методы в скрипт\"},{\"block\":\"p\",\"content\":\"Теперь нам требуется добавить методы в скрипт.\"},{\"block\":\"code\",\"language\":\"C#\",\"content\":\"private void Start()\\n{\\n    rb = GetComponent<Rigidbody2D>();\\n}\\n\\nprivate void FixedUpdate()\\n{\\n    moveInput = Input.GetAxis(\\\"Horizontal\\\");\\n    rb.velocity = new Vector2(moveInput * speed, rb.velocity.y);\\n\\n    if(moveInput != 0) flipValue = FlipValue(moveInput);\\n    transform.eulerAngles = VectorFlip(flipValue);\\n}\\n\\nprivate void Update()\\n{\\n    if (Input.GetKeyDown(KeyCode.Space)) Jump();\\n}\\n\\nprivate void Jump()\\n{\\n    if (Ground()) rb.velocity = Vector2.up * jumpForce;\\n}\\n\\nprivate Vector3 VectorFlip(float count)\\n{\\n    Vector3 vector = new Vector3(0, count, 0);\\n    return vector;\\n}\\n\\nprivate float FlipValue(float count)\\n{\\n    if (count < 0) return 180;\\n    return 0;\\n}\\n\\nprivate bool Ground()\\n{\\n    return Physics2D.OverlapCircle(groundPoint.position, 0.25f, groundLayer) != null;\\n}\"},{\"block\":\"p\",\"content\":\"Разберем добавленные в скрипт методы:\"},{\"block\":\"ul\",\"items\":[\"Start(): данный метод выполняется один раз при инициализации игры.\",\"FixedUpdate(): выполняется каждую секунду 50 раз.\",\"Update(): выполняется то количество раз, сколько FPS в игре.\",\"Jump(): метод, выполняющий прыжок в игре.\",\"VectorFlip(): вспомогательный метод для поворота игрока.\",\"FlipValue(): вспомогательный метод для поворота игрока.\",\"Ground(): метод, возвращающий параметр bool: есть ли земля под игроком.\"]},{\"block\":\"quote\",\"content\":\"FPS — количество сменяемых кадров за единицу времени.\"},{\"block\":\"p\",\"content\":\"Метод может возвращать определенный параметр. Для этого следует использовать следующую конструкцию:\"},{\"block\":\"code\",\"language\":\"C#\",\"content\":\"private <тип_данных> <название_метода>()\\n{\\n    return <значение>;\\n}\"},{\"block\":\"p\",\"content\":\"Вместо ключевого слова «void» следует использовать тот тип данных, который будет возвращаться методом. А для возврата используйте ключевое слово «return». После «return» указывается параметр, который будет возвращаться.\"},{\"block\":\"h2\",\"content\":\"Подробнее про методы скрипта\"},{\"block\":\"p\",\"content\":\"В методе Start() мы обращаемся к физике объекта. Это нужно для того, чтобы в нашем поле «rb» хранилась ссылка на физику игрока.\"},{\"block\":\"p\",\"content\":\"В методе FixedUpdate() хранится логика для перемещения.\"},{\"block\":\"p\",\"content\":\"`moveInput = Input.GetAxis(\\\"Horizontal\\\");`\"},{\"block\":\"p\",\"content\":\"Получаем информацию о вводе по горизонтали. Если говорить иначе: это информация о вводе кнопок «A» и «D» на компьютере. Если мы вводим «A», параметр изменяет значение от «0» до «-1». Если «D» — то от «0» до «1».\"},{\"block\":\"p\",\"content\":\"`rb.velocity = new Vector2(moveInput * speed, rb.velocity.y);`\"},{\"block\":\"p\",\"content\":\"Данное поле отвечает за вектор скорости. Для передвижения мы изменяем поле по оси «X», поэтому задаем ему значение: «moveInput * speed».\"},{\"block\":\"p\",\"content\":\"`if(moveInput != 0) flipValue = FlipValue(moveInput);`\"},{\"block\":\"p\",\"content\":\"Здесь, если мы двигаемся: «if(moveInput != 0)», то совершаем поворот игрока.\"},{\"block\":\"p\",\"content\":\"`transform.eulerAngles = VectorFlip(flipValue);`\"},{\"block\":\"p\",\"content\":\"Здесь мы задаем поворот игрока.\"},{\"block\":\"p\",\"content\":\"В методе Update() мы ловим нажатие пробела и вызываем Jump(). Внутри Jump() стоит проверка: `if (Ground()) rb.velocity = Vector2.up * jumpForce;`. Прыжок сработает только тогда, когда метод Ground() вернет «true».\"},{\"block\":\"p\",\"content\":\"Именно так мы решаем ту самую проблему бесконечных прыжков, о которой я говорил в начале курса. Метод Ground() проверяет маленькую окружность радиусом 0.25 вокруг объекта «groundPoint» под ногами игрока: если в эту окружность попал коллайдер со слоем «Ground» — значит, игрок стоит на земле и может прыгнуть. В воздухе окружность ничего не находит, и повторный прыжок не случится.\"},{\"block\":\"p\",\"content\":\"Разберем конструкцию условий. В программировании у нас есть возможность задавать условия. Внутри условия проверяется поле типа bool, которое принимает значение «true» или «false».\"},{\"block\":\"p\",\"content\":\"По умолчанию конструкция условий выглядит следующим образом:\"},{\"block\":\"code\",\"language\":\"C#\",\"content\":\"if(<условие>)\\n{\\n    <правда>\\n}\\nelse\\n{\\n    <ложь>\\n}\"},{\"block\":\"p\",\"content\":\"После ключевого слова «if» стоит условие. Условие может быть представлено совокупностью условий или одним параметром bool.\"},{\"block\":\"p\",\"content\":\"После условия стоит блок: «правда». Данный блок выполнится в том случае, если условие является правдой. К примеру, «5 >= 3» является правдой. Но вот уже условие «3 > 5» не является правдой, поэтому выполнится условие «ложь».\"},{\"block\":\"p\",\"content\":\"Условия проверки задаются следующими конструкциями:\"},{\"block\":\"ul\",\"items\":[\"«A == B»: A равно B\",\"«A > B»: A больше B\",\"«A < B»: A меньше B\",\"«A >= B»: A больше или равно B\",\"«A <= B»: A меньше или равно B\",\"«A != B»: A не равно B\"]},{\"block\":\"p\",\"content\":\"В разных языках программирования используются немного разные конструкции для того, чтобы сравнивать поля. Данный пример рассмотрен в случае для языка программирования C#.\"},{\"block\":\"p\",\"content\":\"Помимо «if» и «else» еще существует конструкция «else if», в которую можно задать условие, если блок «if» не выполнится. Вот пример кода:\"},{\"block\":\"code\",\"language\":\"C#\",\"content\":\"if(A > B) {\\n    // A больше B\\n}\\nelse if(A == B) {\\n    // A равно B\\n}\\nelse {\\n    // A меньше B\\n}\"},{\"block\":\"h2\",\"content\":\"Добавляем скрипт на игрока\"},{\"block\":\"p\",\"content\":\"Переходим к игровому движку. Выбираем нашего игрока в поле Иерархии. Справа в инспекторе внизу выбираем поле «Add Component» и пишем название нашего скрипта: «PlayerMovable».\"},{\"block\":\"p\",\"content\":\"После добавления скрипта он отобразится справа в Инспекторе. Теперь нам требуется добавить точку для касания с землей и слой, отвечающий за землю.\"},{\"block\":\"h2\",\"content\":\"Добавляем точку для касания с землей\"},{\"block\":\"p\",\"content\":\"Выбираем нашего игрока. Делаем правый клик мыши внутри поля Иерархии. Выбираем: «Create Empty». Даем название объекту: «groundPoint». Перетягиваем объект ближе к низу нашего игрока. И получаем такой результат:\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less8/less8__01.jpg\",\"alt\":\"Игровое пространство Unity\"},{\"block\":\"p\",\"content\":\"Теперь перейдем к созданию слоя, который будет отвечать за «землю» в игре.\"},{\"block\":\"p\",\"content\":\"Выберем платформу слева. Перейдем к Инспектору. Вверху выберем поле «Layer». Выберем данное поле и нажмем на «Add Layer». Далее, в поле Инспектора у нас появится возможность добавить новый слой. Выбираем любое пустое поле и даем ему название «Ground».\"},{\"block\":\"p\",\"content\":\"После чего заново выбираем нашу платформу и выбираем для нее наш новый слой «Ground».\"},{\"block\":\"h2\",\"content\":\"Добавляем объекты в скрипт игрока\"},{\"block\":\"p\",\"content\":\"Переходим к объекту игрока. У скрипта «PlayerMovable» есть 2 поля: Ground Point и Ground Layer. В первое поле нужно перетащить наш объект «groundPoint». Для этого мы можем выбрать объект «groundPoint» у игрока и перетащить в данное поле.\"},{\"block\":\"p\",\"content\":\"Для выбора второго поля мы должны поменять поле «Nothing» на «Ground».\"},{\"block\":\"h2\",\"content\":\"Запускаем игру\"},{\"block\":\"p\",\"content\":\"Можем перейти к запуску игры и попробовать поиграть в нее. Теперь у нас есть возможность перемещаться по платформе. Столкнуть врага с платформы.\"},{\"block\":\"h2\",\"content\":\"Скрипт для жизней\"},{\"block\":\"p\",\"content\":\"Добавим еще 2 скрипта: «PlayerHealth», «PlayerTouch». Первый скрипт будет отвечать за здоровье игрока. А скрипт «PlayerTouch» будет отвечать за обработку касаний игрока с объектами.\"},{\"block\":\"p\",\"content\":\"Сразу добавим 2 этих скрипта на игрока. Перейдем к написанию «PlayerHealth».\"},{\"block\":\"code\",\"language\":\"C#\",\"content\":\"using UnityEngine.SceneManagement;\\nusing System.Collections;\\nusing System.Collections.Generic;\\nusing UnityEngine;\\n\\npublic class PlayerHealth : MonoBehaviour\\n{\\n    private float maxHealth = 10f;\\n    private float health;\\n\\n    private void Start()\\n    {\\n        health = maxHealth;\\n        Health();\\n    }\\n\\n    private void Health()\\n    {\\n        if(health <= 0f) InvokeNullHealth();\\n\\n        if(health > maxHealth) health = maxHealth;\\n\\n        Debug.Log(\\\"Health: \\\" + health);\\n    }\\n\\n    public void Damage(float damage)\\n    {\\n        ChangeHealth(-damage);\\n    }\\n\\n    private void ChangeHealth(float change)\\n    {\\n        health += change;\\n        Health();\\n    }\\n\\n    private void InvokeNullHealth()\\n    {\\n        SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex);\\n    }\\n\\n}\"},{\"block\":\"h2\",\"content\":\"Разберем данный скрипт подробнее.\"},{\"block\":\"p\",\"content\":\"В начале мы подключаем библиотеку «using UnityEngine.SceneManagement;». Данная библиотека даст нам возможность работать со сценами: загружать их, перезагружать страницу и прочее.\"},{\"block\":\"p\",\"content\":\"Далее мы используем 2 поля: `health` и `maxHealth`. Первое поле отвечает за текущее значение жизней. Второе поле отвечает за максимальное количество жизней.\"},{\"block\":\"p\",\"content\":\"Далее, методы скрипта. В методе `Start()` мы задаем жизням максимальное значение жизней. Следующая строка — вызов метода `Health()`. Данный метод проверяет следующие условия: жизней меньше или равно 0 — вызываем метод `InvokeNullHealth()`, жизней больше чем максимальное количество — присваиваем жизням максимальное количество жизней, чтобы не выйти за лимит максимального количества жизней. И в остальных случаях мы выводим на экран количество жизней: «Debug.Log(\\\"Health: \\\" + health);».\"},{\"block\":\"p\",\"content\":\"Еще в данном классе описано 3 метода: Damage(float damage), ChangeHealth(float change) и InvokeNullHealth().\"},{\"block\":\"p\",\"content\":\"Первый метод принимает параметр в круглых скобках. Данный параметр отвечает за количество получаемого урона. Важно: значение указывается по модулю.\"},{\"block\":\"p\",\"content\":\"Метод Damage(float damage) вызывает метод ChangeHealth(float change) и передает ему параметр damage с отрицательным значением.\"},{\"block\":\"p\",\"content\":\"Метод ChangeHealth(float change) изменяет количество жизней и вызывает метод Health() для проверки условий с жизнями.\"},{\"block\":\"p\",\"content\":\"Оставшийся метод — InvokeNullHealth(). Данный метод вызывается, когда количество жизней становится меньше или равно нулю. Данный метод перезагружает сцену с помощью конструкции: «SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex);».\"},{\"block\":\"h2\",\"content\":\"Обработка касания\"},{\"block\":\"p\",\"content\":\"Переходим к написанию скрипта, который будет отвечать за обработку касания игрока.\"},{\"block\":\"code\",\"language\":\"C#\",\"content\":\"using System.Collections;\\nusing System.Collections.Generic;\\nusing UnityEngine;\\n\\npublic class PlayerTouch : MonoBehaviour\\n{\\n    private PlayerHealth health;\\n    private float damage = 1f;\\n\\n    private void Start()\\n    {\\n        health = GetComponent<PlayerHealth>();\\n    }\\n\\n    private void OnCollisionEnter2D(Collision2D collision)\\n    {\\n        Debug.Log(collision.gameObject.tag);\\n    }\\n}\"},{\"block\":\"p\",\"content\":\"Разберем данный скрипт подробнее.\"},{\"block\":\"p\",\"content\":\"В первой строке мы подключаем класс с обработкой жизней, а в методе Start() мы указываем ссылку на объект.\"},{\"block\":\"p\",\"content\":\"Также в данном скрипте обработки касания указан параметр «damage». При столкновении с врагом мы будем получать урон, равный значению «damage».\"},{\"block\":\"p\",\"content\":\"Дальше у нас указана конструкция для обработки касаний. Она называется «OnCollisionEnter2D». Данный метод обрабатывает касания с объектами, у которых имеются физические границы. Спойлер: наш объект может иметь границы, которые обычно называются «триггерами».\"},{\"block\":\"p\",\"content\":\"Сейчас мы в консоль выводим информацию о теге объекта. При запуске игры при любом касании мы будем получать вывод в консоль: «Untagged».\"}]},{\"slug\":\"9\",\"title\":\"9. Теги. Урон. Пополнение здоровья\",\"short\":\"Теги. Урон. Пополнение здоровья\",\"content\":[{\"block\":\"p\",\"content\":\"В данном уроке мы завершим работу над обработкой касаний, добавим пополнение здоровья и добавим теги на объекты.\"},{\"block\":\"h2\",\"content\":\"Обработка касаний\"},{\"block\":\"p\",\"content\":\"Немного изменим обработку касаний игрока с объектами. Сейчас мы только выводим тег объекта, с которым касаемся. Теперь вместо вывода мы поставим данный блок кода: «if (collision.gameObject.CompareTag(\\\"Enemy\\\")) health.Damage(damage);».\"},{\"block\":\"p\",\"content\":\"С его помощью при касании игрока с врагом мы вызовем метод, который обработает урон.\"},{\"block\":\"h2\",\"content\":\"Тег на врага\"},{\"block\":\"p\",\"content\":\"Теперь добавим тег, отвечающий за врага. Перейдем в сцену. Выберем нашего врага — объект «Enemy». И в поле Инспектора выберем поле «Tag» сверху. Нажмем на «Untagged», выберем «Add Tag…». Нажмем на плюс, добавим новый тег: «Enemy». Теперь заново выберем врага и дадим ему наш новый тег.\"},{\"block\":\"p\",\"content\":\"Теперь у врага есть тег, и мы можем обработать с ним касание. Запустим игру. При касании игрока с врагом мы будем получать урон. Наш уровень здоровья будет уменьшаться. Отследить здоровье мы можем в окне Консоли.\"},{\"block\":\"h2\",\"content\":\"Тег для здоровья\"},{\"block\":\"p\",\"content\":\"Теперь обработаем получение здоровья. Добавим еще один тег: «Eat». Добавим данный тег на объект «Eat».\"},{\"block\":\"p\",\"content\":\"И пока мы находимся в объекте «Eat», нам нужно перейти к компоненту «Circle Collider 2D». Нам нужно активировать поле «Is Trigger» для того, чтобы мы могли обрабатывать касание с объектом и, при этом, мы бы проходили сквозь объект.\"},{\"block\":\"h2\",\"content\":\"Обработка касания с едой\"},{\"block\":\"p\",\"content\":\"Перейдем к обработке касание с нашим объектом «Eat». Откроем скрипт «PlayerTouch».\"},{\"block\":\"p\",\"content\":\"Первое, что я хочу сделать: изменить название поля «damage» на «valuechange». Изменим упоминание данного поля на новое название. Изменение связано с тем, что на это же значение мы будем убавлять и прибавлять здоровье.\"},{\"block\":\"p\",\"content\":\"Далее — добавим обработку касание с триггером.\"},{\"block\":\"code\",\"language\":\"C#\",\"content\":\"private void OnTriggerEnter2D(Collider2D collider)\\n{\\n    if(collider.gameObject.CompareTag(\\\"Eat\\\")) health.Eat(valuechange);\\n}\"},{\"block\":\"p\",\"content\":\"Мы добавили условие обработки касания с объектом еды. Сейчас логика работы будет следующая: мы коснемся еды, получим здоровье, но объект останется. Давайте сделаем так, чтобы объект пропадал при касании.\"},{\"block\":\"code\",\"language\":\"C#\",\"content\":\"private void OnTriggerEnter2D(Collider2D collider)\\n{\\n    if(collider.gameObject.CompareTag(\\\"Eat\\\"))\\n    {\\n        health.Eat(valuechange);\\n        Destroy(collider.gameObject);\\n    }\\n}\"},{\"block\":\"p\",\"content\":\"Теперь при касании мы будем уничтожать наш объект. Осталось добавить метод Eat() для скрипта «PlayerHealth».\"},{\"block\":\"code\",\"language\":\"C#\",\"content\":\"public void Eat(float eat)\\n{\\n    ChangeHealth(eat);\\n}\"},{\"block\":\"p\",\"content\":\"Теперь мы можем не только получать урон, но и пополнять здоровье. Обратите внимание на одну особенность: OnCollisionEnter2D срабатывает только в момент касания, поэтому если игрок просто стоит на враге, урон больше не наносится. Для постоянного урона понадобился бы OnCollisionStay2D с задержкой между попаданиями — попробуйте добавить это самостоятельно.\"},{\"block\":\"h2\",\"content\":\"Итоговый скрипт PlayerTouch\"},{\"block\":\"p\",\"content\":\"Мы правили этот скрипт по частям, поэтому приведу его целиком — сверьтесь со своим кодом. Обратите внимание, что поле «damage» здесь уже называется «valuechange».\"},{\"block\":\"code\",\"language\":\"C#\",\"content\":\"using System.Collections;\\nusing System.Collections.Generic;\\nusing UnityEngine;\\n\\npublic class PlayerTouch : MonoBehaviour\\n{\\n    private PlayerHealth health;\\n    private float valuechange = 1f;\\n\\n    private void Start()\\n    {\\n        health = GetComponent<PlayerHealth>();\\n    }\\n\\n    private void OnCollisionEnter2D(Collision2D collision)\\n    {\\n        if (collision.gameObject.CompareTag(\\\"Enemy\\\")) health.Damage(valuechange);\\n    }\\n\\n    private void OnTriggerEnter2D(Collider2D collider)\\n    {\\n        if (collider.gameObject.CompareTag(\\\"Eat\\\"))\\n        {\\n            health.Eat(valuechange);\\n            Destroy(collider.gameObject);\\n        }\\n    }\\n}\"},{\"block\":\"p\",\"content\":\"Отлично!\"}]},{\"slug\":\"10\",\"title\":\"10. Меню\",\"short\":\"Меню\",\"content\":[{\"block\":\"p\",\"content\":\"Последний урок в данном курсе. Здесь мы добавим сцену меню для нашей игры. Начнем же!\"},{\"block\":\"p\",\"content\":\"Перейдем к сцене «Menu». Поработаем над интерфейсом игры.\"},{\"block\":\"p\",\"content\":\"Изменим название камеры на «camera».\"},{\"block\":\"h2\",\"content\":\"Интерфейс\"},{\"block\":\"p\",\"content\":\"В поле Иерархии нажмем правой кнопкой мыши, выберем «UI > Image». Так мы создадим интерфейс для игры и добавим изображение.\"},{\"block\":\"p\",\"content\":\"У нас создастся 3 объекта: Canvas, Image и EventSystem.\"},{\"block\":\"p\",\"content\":\"Canvas — это объект, который отвечает за интерфейс в игре.\"},{\"block\":\"quote\",\"content\":\"Интерфейс — это набор инструментов, который позволяет пользователю взаимодействовать с программой.\"},{\"block\":\"p\",\"content\":\"Image — это добавленная нами картинка. Мы сделаем из нее задний фон.\"},{\"block\":\"p\",\"content\":\"EventSystem — это объект, который будет обрабатывать касания с объектами в интерфейсе.\"},{\"block\":\"h2\",\"content\":\"Изменяем названия\"},{\"block\":\"p\",\"content\":\"Лично я изменю названия «Canvas», «Image» и «EventSystem» на «canvas», «background» и «event» соответственно.\"},{\"block\":\"h2\",\"content\":\"Меняем обработку интерфейса\"},{\"block\":\"p\",\"content\":\"Теперь нам нужно изменить вид интерфейса. Для этого перейдем в объект «canvas» и изменим 2 поля. Первое поле: компонент «Canvas», поле «Render Mode» на «Screen Space - Camera». В поле «Render Camera» перетягиваем нашу камеру из окна Иерархии.\"},{\"block\":\"p\",\"content\":\"Следующее поле для изменения: «UI Scale Mode» у компонента «Canvas Scaler». Изменяем поле на «Scale With Screen Size». Изменяем координаты «Reference Resolution», «X»: «1920», «Y»: «1080». Теперь наш интерфейс изменяется в соответствии с размерами экрана.\"},{\"block\":\"h2\",\"content\":\"Растягиваем фоновое изображение\"},{\"block\":\"p\",\"content\":\"Теперь нам требуется растянуть фоновое изображение на весь экран. Для этого выберем наш объект «background», переходим в окно Инспектора.\"},{\"block\":\"p\",\"content\":\"Выбираем компонент «Rect Transform» и изменяем поле слева вверху.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less10/less10__01.jpg\",\"alt\":\"Игровой компонент Unity\"},{\"block\":\"p\",\"content\":\"У нас появится окно. В данном окне мы можем выбрать, как будет располагаться объект относительно родителя. Нам нужно зажать кнопку «Alt» («Option») и выбрать правый нижний вариант расположения.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less10/less10__02.jpg\",\"alt\":\"Игровой компонент Unity\"},{\"block\":\"h2\",\"content\":\"Изменяем цвет\"},{\"block\":\"p\",\"content\":\"Теперь изменим цвет фона на #ADCDC4.\"},{\"block\":\"h2\",\"content\":\"Добавляем название игры\"},{\"block\":\"p\",\"content\":\"Теперь нам требуется добавить название игры. Нажимаем на объект «canvas», нажимаем правой кнопкой мыши и выбираем: «UI > Legacy > Text». Так мы добавим текст в наше меню.\"},{\"block\":\"img\",\"src\":\"/courses/unity-first-game/less10/less10__03.jpg\",\"alt\":\"Игровой компонент Unity\"},{\"block\":\"p\",\"content\":\"Настроим название игры в соответствии с изображением.\"},{\"block\":\"h2\",\"content\":\"Кнопка «Начать»\"},{\"block\":\"p\",\"content\":\"Теперь создадим кнопку «Начать игру».\"},{\"block\":\"p\",\"content\":\"Для этого создадим изображение. Изменим размер на «Width»: «600» и «Height»: «200». Изменим название на «button».\"},{\"block\":\"p\",\"content\":\"Теперь создадим текст в кнопке. Выбираем нашу кнопку и создаем «Text». Даем название: «text». Растянем текст на всю кнопку.\"},{\"block\":\"p\",\"content\":\"Снова выберем кнопку. Добавим на нее компонент «Button». Теперь у нас есть возможность нажимать на нашу кнопку.\"},{\"block\":\"h2\",\"content\":\"Добавляем первый объект для выбора\"},{\"block\":\"p\",\"content\":\"Чтобы в Консоли не было ошибок, мы должны выбрать объект «event», компонент «Event System», изменить поле «First Selected». Сюда мы должны «положить» наш объект кнопку.\"},{\"block\":\"h2\",\"content\":\"Начало игры\"},{\"block\":\"p\",\"content\":\"Теперь требуется написать логику для работы кнопки. Создадим скрипт «LoadLevel».\"},{\"block\":\"code\",\"language\":\"C#\",\"content\":\"using UnityEngine.SceneManagement;\\nusing System.Collections;\\nusing System.Collections.Generic;\\nusing UnityEngine;\\n\\npublic class LoadLevel : MonoBehaviour\\n{\\n    public void Menu()\\n    {\\n        Load(\\\"Menu\\\");\\n    }\\n\\n    public void Game()\\n    {\\n        Load(\\\"Game\\\");\\n    }\\n\\n    private void Load(string name)\\n    {\\n        SceneManager.LoadScene(name);\\n    }\\n}\"},{\"block\":\"p\",\"content\":\"Скрипт небольшой. Метод «Load» отвечает за загрузку уровня по его названию. Метод «Menu» отвечает за загрузку меню. Метод «Game» отвечает за загрузку игры.\"},{\"block\":\"h2\",\"content\":\"Добавляем объект со скриптами\"},{\"block\":\"p\",\"content\":\"Теперь нам требуется добавить объект со скриптами. Откроем нашу сцену. Добавим 2 пустых объекта: один с названием «---», другой с названием «scripts».\"},{\"block\":\"p\",\"content\":\"Первый объект исключительно для удобства. На второй объект нам нужно повесить скрипт «LoadLevel».\"},{\"block\":\"h2\",\"content\":\"Добавляем обработчик нажатий\"},{\"block\":\"p\",\"content\":\"Теперь выбираем нашу кнопку. Переходим к компоненту «Button». Выбираем поле «On Click ()». Нажимаем на плюс. В появившимся поле добавляем объект «scripts». Далее — «No Function» изменяем на «LoadLevel > Game()».\"},{\"block\":\"h2\",\"content\":\"Завершение\"},{\"block\":\"p\",\"content\":\"Мы завершили курс. Теперь у вас есть готовый 2D-платформер с меню, который можно собрать под Android или Windows — развивайте его дальше.\"}]}]',
        @owner, 1, '2020-01-01 00:00:00', '2023-07-01 00:00:00')
