-- Простейший сайт на HTML и CSS: 9 стр.
INSERT INTO courses (id, title, subtitle, accent, section, difficulty, level, duration, image, video, chips, github, author, certificate, about, pages, user_id, disabled, created_at, updated_at)
VALUES ('html-css-first-site',
        'Простейший сайт на HTML и CSS',
        'Разметка, стили и первая страница, которую можно показать друзьям и открыть в интернете.',
        'mint',
        'web',
        1,
        'Для начинающих',
        '7 уроков',
        '/img/courses/html-css-first-site/cover.jpg',
        NULL,
        '[\"HTML\",\"CSS\",\"Вёрстка\",\"GitHub Pages\"]',
        'https://github.com/DanyaBooba/example-site',
        '{\"name\":\"Даниил Дыбка\",\"email\":\"daniil@dybka.ru\",\"telegram\":\"https://ddybka.t.me\"}',
        NULL,
        '[{\"block\":\"p\",\"content\":\"Курс про то, как создаются сайты — на простых примерах и без лишней теории. Начинаем с пустой папки и редактора кода, а заканчиваем страницей, которая открывается по обычной ссылке в интернете.\"},{\"block\":\"h2\",\"content\":\"Что вы соберёте\"},{\"block\":\"p\",\"content\":\"Все уроки — это одна страница, которая растёт от урока к уроку. Ничего не выбрасывается: сначала появляется текст, потом цвета, потом шапка, содержимое и подвал, а в конце всё это уезжает на хостинг.\"},{\"block\":\"ul\",\"items\":[\"Первую страницу `index.html` и её структуру из тегов\",\"Оформление через CSS: цвета, отступы, выравнивание\",\"Классы и отдельный блок стилей вместо атрибутов `style`\",\"Каркас страницы: шапка, содержимое, подвал\",\"Семантические теги вместо `div` — и зачем это поисковым роботам\",\"Картинки и ссылки между страницами\",\"Публикацию сайта на GitHub Pages — бесплатно и по настоящей ссылке\"]},{\"block\":\"h2\",\"content\":\"Кому подойдёт\"},{\"block\":\"p\",\"content\":\"Курс рассчитан на полных новичков: опыт в программировании не нужен. HTML и CSS — это не языки программирования, и чтобы начать, достаточно редактора кода и браузера.\"},{\"block\":\"h2\",\"content\":\"Как проходить\"},{\"block\":\"ol\",\"items\":[\"Откройте урок и свою папку с сайтом рядом\",\"Повторяйте код руками, а не копируйте целиком\",\"После каждого изменения открывайте страницу в браузере и смотрите результат\"]},{\"block\":\"h2\",\"content\":\"Что потребуется\"},{\"block\":\"table\",\"head\":[\"Что\",\"Подробности\"],\"rows\":[[\"Компьютер\",\"Windows, macOS или Linux — без разницы\"],[\"Редактор кода\",\"Visual Studio Code, Rider, Notepad++ или другой\"],[\"Браузер\",\"Любой современный: Chrome, Safari, Firefox\"],[\"Аккаунт GitHub\",\"Нужен только в последнем уроке, для публикации\"]]},{\"block\":\"h2\",\"content\":\"Результат\"},{\"block\":\"p\",\"content\":\"Свёрстанная страница, опубликованная в интернете.\"}]',
        '[{\"slug\":\"1\",\"title\":\"1. Первая страница сайта\",\"short\":\"Первая страница сайта\",\"content\":[{\"block\":\"p\",\"content\":\"Навык создания сайтов один из основных в IT-индустрии, потому что не требует глубоких знаний в программировании. Очень часто возникает задача оформить страницу, создать лендинг или просто показать информацию в интернете. Именно этому мы и научимся в этом курсе.\"},{\"block\":\"h2\",\"content\":\"Подготовка\"},{\"block\":\"p\",\"content\":\"Чтобы начать работу, нам необходимо установить редактор кода. Я использую Visual Studio Code, но можно и другие рассмотреть (например Rider, Notepad++ и прочие).\"},{\"block\":\"p\",\"content\":\"Скачать Visual Studio Code можно на официальном сайте: [https://code.visualstudio.com/Download/](https://code.visualstudio.com/Download/)\"},{\"block\":\"h3\",\"content\":\"Редактор кода\"},{\"block\":\"p\",\"content\":\"Давайте чуть подробнее поговорим, что такое редактор кода и как с ним работать.\"},{\"block\":\"p\",\"content\":\"Программисты пишут свои программы не просто в текстовом редакторе, а в специальных программах, называемых редакторами кода. Их большое количество для разных языков программирования. В нашем случае мы будем использовать один из самых популярных — Visual Studio Code. Он подходит не только для создания сайтов, но и для других языков программирования.\"},{\"block\":\"img\",\"src\":\"/img/courses/html-css-first-site/1-0.jpg\"},{\"block\":\"p\",\"content\":\"Так выглядит интерфейс программы. Слева мы можем открыть папку с проектом, в центре экрана будет открываться файл. Все как обычный редактор текста, но прокаченный. В нем есть подсветка синтаксиса, автодополнение, поиск по проекту и много других полезных функций.\"},{\"block\":\"h3\",\"content\":\"Подготовим редактор для работы\"},{\"block\":\"p\",\"content\":\"Слева нажмите на «Open Folder» и выберите папку, в которой будет находиться ваш сайт. Если такой папки нет, создайте ее.\"},{\"block\":\"img\",\"src\":\"/img/courses/html-css-first-site/1-0-2.jpg\"},{\"block\":\"p\",\"content\":\"Слева вы увидите открытую папку. Чтобы создать новый файл, нажмите правой кнопкой мыши по папке и выберите «New File». Или используйте двойной клик по папке в пустой области.\"},{\"block\":\"h2\",\"content\":\"Создаем файлы\"},{\"block\":\"p\",\"content\":\"Теперь можем начать создавать сайт.\"},{\"block\":\"p\",\"content\":\"Сайты — это набор страниц, каждая страница — это отдельный файл. Чтобы нам создать первую страницу сайта, создадим файл `index.html` и добавим в него следующее содержимое:\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<!DOCTYPE html>\\n<html lang=\\\"en\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n    <title>Document</title>\\n</head>\\n<body>\\n</body>\\n</html>\"},{\"block\":\"p\",\"content\":\"Это и есть наш первый сайт и первая его страница. Правда она пока что ничего не показывает. Давайте добавим какой-нибудь текст. Между `<body>` и `</body>` напишем текст «Привет, мир!»\"},{\"block\":\"p\",\"content\":\"Теперь чтобы посмотреть на результат достаточно нажать правой кнопкой мыши по файлу и открыть его в любом удобном браузере, например в Google Chrome.\"},{\"block\":\"img\",\"src\":\"/img/courses/html-css-first-site/1-1.jpg\",\"alt\":\"Первая страница сайта в браузере\"},{\"block\":\"p\",\"content\":\"Такой результат мы увидим: черный текст на белом фоне. Слишком скучно, добавим красок. Давайте покрасим фон в синий, а текст в красный. Чтобы это сделать, вместо обычного `<body>` напишем следующее:\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<body style=\\\"background-color: blue\\\">\"},{\"block\":\"p\",\"content\":\"Цвет можно задать словом либо числовым значением. Например, вместо «blue» можно написать «#0000FF».\"},{\"block\":\"p\",\"content\":\"Есть небольшой перечень цветов, которые можно задать словом: `black`, `white`, `red`, `green`, `blue`, `yellow`, `gray` и прочие. Остальные цвета задаются числовым значением в формате HEX.\"},{\"block\":\"p\",\"content\":\"HEX — это формат вида `#RRGGBB`, где `RR` — значение красного, `GG` — зеленого, `BB` — синего компонентов цвета. Каждое значение может быть от `00` до `FF` в шестнадцатеричной системе исчисления. Например, `#FF0000` — это красный цвет, `#00FF00` — зеленый, `#0000FF` — синий.\"},{\"block\":\"p\",\"content\":\"Еще цвета можно задавать в формате RGB, например `rgb(255, 0, 0)` — это красный цвет, `rgb(0, 255, 0)` — зеленый, `rgb(0, 0, 255)` — синий.\"},{\"block\":\"p\",\"content\":\"Чтобы изменить цвет текста, потребуется немного больше изменений. Для начала уберем прошлый текст «Привет, мир!» и заменим его на следующую конструкцию:\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<p style=\\\"color: red\\\">\\n    Привет, мир!\\n</p>\"},{\"block\":\"p\",\"content\":\"Можете заметить, что мы обернули текст в 2 специальные конструкции. Внутри первой мы снова задали цвет, только теперь не через цвет фона (`background-color`), а через цвет самого текста (`color`).\"},{\"block\":\"h2\",\"content\":\"Теги\"},{\"block\":\"p\",\"content\":\"Что за конструкции мы наблюдаем в файле? Я говорю про `<html>`, `<head>`, `<body>`, `<p>` и прочих.\"},{\"block\":\"p\",\"content\":\"Это все называется тегами. Их можно представлять как строительные блоки. Каждый тег имеет свое название. Может содержать «настройки» (атрибуты). И имеет свое назначение.\"},{\"block\":\"p\",\"content\":\"Например, первый тег в файле `<!DOCTYPE html>` сообщает о HTML-разметке (что файл содержит её). Далее идет общий тег `<html>`, причем в начале файла он открывается, а в конце файла — закрывается. Увидеть это мы можем по символу слеша «/» перед названием тега (в случае закрывающегося).\"},{\"block\":\"p\",\"content\":\"То есть, тег устроен следующим образом. В начале стоит символ меньше `<`. Дальше идет название тега. Через пробел могут идти «настройки» (атрибуты) тега. И в конце символ больше `>`.\"},{\"block\":\"h3\",\"content\":\"Открывающие, закрывающие и одинарные теги\"},{\"block\":\"p\",\"content\":\"Теги могут быть одинарными. Например внутри тега `<head>` есть тег `<meta charset=\\\"UTF-8\\\">` — он не имеет закрывающего, потому что в него нельзя поместить какое-то содержимое (текст или другой тег), как мы это делаем с другими: внутрь тега помещаем содержимое.\"},{\"block\":\"h3\",\"content\":\"«Настройки» тега\"},{\"block\":\"p\",\"content\":\"Теперь поговорим про те самые «настройки» тега, которые я почему-то пишу через кавычки. Сам по себе тег несет информацию «О чем тег?», но мы можем уточнить или изменить его работу. Для этого необходимо добавить атрибуты к нему.\"},{\"block\":\"p\",\"content\":\"Атрибуты тега пишутся через пробел после его названия и до символа больше `>` внутри открывающего тега.\"},{\"block\":\"p\",\"content\":\"Вот например наш тег:\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<html lang=\\\"en\\\">\"},{\"block\":\"p\",\"content\":\"`lang` — это его атрибут. С помощью него мы уточняем язык страницы для незрячих людей. Дальше пишется значение атрибута, по умолчанию «en» (английский язык). Давайте заменим его на русский, вместо «en» напишем «ru»:\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<html lang=\\\"ru\\\">\"},{\"block\":\"p\",\"content\":\"Или например изменение цвета текста:\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<p style=\\\"color: red\\\">\"},{\"block\":\"p\",\"content\":\"В открывающем теге `<p>` мы пишем атрибут `style` со значением `color: red`.\"}]},{\"slug\":\"2\",\"title\":\"2. Как устроен сайт\",\"short\":\"Как устроен сайт\",\"content\":[{\"block\":\"p\",\"content\":\"В прошлом уроке мы поговорили о том, что страницы сайта создаются при помощи тегов, а для тегов мы можем добавить определенные атрибуты. Давайте поговорим об этом чуть подробнее.\"},{\"block\":\"h2\",\"content\":\"Устройство сайта\"},{\"block\":\"p\",\"content\":\"Теперь мы можем чуть подробнее поговорить о том, как работает сайт. Итак, сайты создаются при помощи 3 вещей:\"},{\"block\":\"ul\",\"items\":[\"**HTML-страницы.** То, что мы делали на прошлом уроке. Это каркас для здания.\",\"**CSS-стили.** При помощи них мы добавляем цвета и дизайн к страницам.\",\"**JavaScript-код.** Это выполнение скриптов и какая-то автоматизация на сайте. К примеру, чтобы после нажатия на кнопку появлялось модальное окно.\"]},{\"block\":\"note\",\"content\":\"HTML и CSS — это не языки программирования! Запомните это.\"},{\"block\":\"p\",\"content\":\"Единственный язык программирования для сайтов — это JavaScript. Здесь есть нюансы, к примеру уже для серверной части мы можем использовать практически любой язык программирования. Но в визуальной части JavaScript — единственный язык программирования. Единственный в 2 смыслах: HTML и CSS не языки программирования + для визуальной части сайта у нас нет других языков программирования, только JavaScript.\"},{\"block\":\"h2\",\"content\":\"Теги\"},{\"block\":\"p\",\"content\":\"Теперь про теги. Как уже было сказано на прошлом уроке, есть множество разных тегов. Они отличаются по своему названию. Название тега пишется после знака меньше `<`. Вот основные теги:\"},{\"block\":\"table\",\"head\":[\"Тег\",\"Назначение\"],\"rows\":[[\"`html`\",\"«обертка» страницы\"],[\"`head`\",\"секция «Заголовок» на странице\"],[\"`body`\",\"секция «Тело» на странице\"],[\"`div`\",\"«строительный» блок\"],[\"`h1`…`h6`\",\"заголовки от 1 до 6 уровня (от наибольшего к наименьшему)\"],[\"`p`\",\"параграф (текст)\"]]},{\"block\":\"h3\",\"content\":\"Зачем нужны все эти теги\"},{\"block\":\"p\",\"content\":\"Каждый тег несет свой функционал. К примеру при помощи тега `html` мы даем понять браузеру содержимое нашей страницы. Тег `head` помогает подключить файлы или настроить отображение страницы. Тег `body` создает видимую часть сайта. А при помощи тегов `div`, `h1`…`h6` и `p` мы создаем саму страницу.\"},{\"block\":\"h2\",\"content\":\"Атрибуты\"},{\"block\":\"p\",\"content\":\"У разных тегов могут быть разные атрибуты. Почти для каждого тега они свои. Разобраться не трудно.\"},{\"block\":\"p\",\"content\":\"Главный атрибут, который нам стоит знать — это `style`, он позволяет для тега добавить CSS-стили (то есть визуально изменить его). В будущем мы познакомимся с атрибутом `class` который делает почти тоже самое.\"},{\"block\":\"p\",\"content\":\"Также для тега `html` можно задать атрибут `lang` со значением языка. Это помогает программам для незрячих людей определить язык текста и правильно его прочитать.\"},{\"block\":\"p\",\"content\":\"Ознакомиться с подробным описанием тегов и атрибутов можно на [документации MDN](https://developer.mozilla.org/ru/docs/Web/HTML/Element) или сайте [«Дока»](https://doka.guide/html/).\"}]},{\"slug\":\"3\",\"title\":\"3. CSS-классы и блок стилей\",\"short\":\"CSS-классы и блок стилей\",\"content\":[{\"block\":\"p\",\"content\":\"Теперь мы с вами знаем, что страницы сайтов строятся при помощи HTML в который мы добавляем CSS. Другими словами, HTML разметка создает структуру сайта, а при помощи CSS стилей мы визуально изменяем их. Давайте познакомимся с CSS поближе.\"},{\"block\":\"h2\",\"content\":\"CSS классы\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<!DOCTYPE html>\\n<html lang=\\\"ru\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n    <title>Document</title>\\n</head>\\n<body style=\\\"background-color: blue\\\">\\n    <p style=\\\"color: red\\\">\\n        Привет, мир!\\n    </p>\\n</body>\\n</html>\"},{\"block\":\"p\",\"content\":\"Вот код с нашего первого урока. К тегам `body` и `p` мы добавили атрибут `style` в котором описали их цвета — это и есть применение CSS.\"},{\"block\":\"p\",\"content\":\"В данном примере мы явно задали значения цветов для данных 2 блоков. Но также мы можем задать класс для тегов и описывать CSS внутри каждого класса. Давайте попробуем.\"},{\"block\":\"p\",\"content\":\"В начале я уберу атрибуты `style` у наших блоков и вместо них создам атрибут `class` следующим образом.\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<!DOCTYPE html>\\n<html lang=\\\"ru\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n    <title>Document</title>\\n</head>\\n<body class=\\\"body\\\">\\n    <p class=\\\"paragraph\\\">\\n        Привет, мир!\\n    </p>\\n</body>\\n</html>\"},{\"block\":\"p\",\"content\":\"Внутри атрибута `class` я задаю значение самого класса. Название для классов могу выбрать почти любое, главное на английском, можно использовать черточку `-` и знак подчеркивания `_`.\"},{\"block\":\"p\",\"content\":\"Теперь мне нужно описать, как будут выглядеть блоки данных классов. Давайте сделаем это.\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<!DOCTYPE html>\\n<html lang=\\\"ru\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n    <title>Document</title>\\n    <style>\\n        .body {\\n            background-color: gray;\\n        }\\n        .paragraph {\\n            color: red;\\n        }\\n    </style>\\n</head>\\n<body class=\\\"body\\\">\\n    <p class=\\\"paragraph\\\">\\n        Привет, мир!\\n    </p>\\n</body>\\n</html>\"},{\"block\":\"p\",\"content\":\"Внутри тега `head` я создал новый тег `style`, в этом теге находятся CSS стили страницы. Тегов `style` может быть любое количество.\"},{\"block\":\"p\",\"content\":\"Внутри тега `style` я пишу CSS: через точку я пишу название класса, внутри фигурных скобок класса я описываю как он должен выглядеть. Перенес стили из прошлого примера. Для фона и параграфа текста.\"},{\"block\":\"h2\",\"content\":\"Стили сразу для всех тегов одного вида\"},{\"block\":\"p\",\"content\":\"Если я хочу задать значения для всех тегов одного вида, тогда нужно написать просто название тега и в фигурных скобках их описывать. Аккуратно, потому что эти свойства будут применены для всех тегов одного вида.\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<!DOCTYPE html>\\n<html lang=\\\"ru\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n    <title>Document</title>\\n    <style>\\n        p {\\n            font-weight: bold;\\n        }\\n    </style>\\n</head>\\n<body>\\n    <p>\\n        Привет, мир!\\n    </p>\\n    <p>\\n        Как дела?\\n    </p>\\n</body>\\n</html>\"},{\"block\":\"p\",\"content\":\"Например, здесь я для параграфа `p` задал стиль жирный. И это будет применено для текста «Привет, мир!» и для текста «Как дела?». А также для всех последующих параграфов `p`.\"},{\"block\":\"img\",\"src\":\"/img/courses/html-css-first-site/3-1.jpg\",\"alt\":\"Оба параграфа стали жирными\"},{\"block\":\"h2\",\"content\":\"Несколько классов для одного тега\"},{\"block\":\"p\",\"content\":\"Для одного тега можно задать несколько классов. Для этого в атрибуте `class` через пробел пишем несколько названий классов. Например:\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<!DOCTYPE html>\\n<html lang=\\\"ru\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n    <title>Document</title>\\n    <style>\\n        .class1 {\\n            background-color: gray;\\n        }\\n\\n        .class2 {\\n            color: red;\\n        }\\n\\n        .class3 {\\n            font-weight: bold;\\n        }\\n    </style>\\n</head>\\n<body>\\n    <p class=\\\"class1 class2 class3\\\">\\n        Привет, мир!\\n    </p>\\n</body>\\n</html>\"},{\"block\":\"p\",\"content\":\"Теперь параграф текста «Привет, мир!» имеет серый фон, красный цвет текста и жирный шрифт. И все задано через свой класс.\"},{\"block\":\"img\",\"src\":\"/img/courses/html-css-first-site/3-2.jpg\"},{\"block\":\"p\",\"content\":\"Разные классы можно использовать для разных тегов. Например, создать общий класс для всех параграфов. Или создать класс для кнопок, их может быть много на странице, но все они будут иметь одинаковый класс. Но, к примеру, разный цвет фона.\"}]},{\"slug\":\"4\",\"title\":\"4. Шапка, содержимое и подвал\",\"short\":\"Шапка, содержимое и подвал\",\"content\":[{\"block\":\"p\",\"content\":\"Давайте поработаем с версткой страницы. Сделаем какой-нибудь простой прототип страницы c шапкой, содержимым и подвалом.\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<!DOCTYPE html>\\n<html lang=\\\"ru\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n    <title>Document</title>\\n</head>\\n<body>\\n    <div>\\n        <h1>Шапка</h1>\\n    </div>\\n    <div>\\n        <p>Содержимое</p>\\n    </div>\\n    <div>\\n        <p>Подвал</p>\\n    </div>\\n</body>\\n</html>\"},{\"block\":\"img\",\"src\":\"/img/courses/html-css-first-site/4-1.jpg\",\"alt\":\"Прототип страницы без стилей\"},{\"block\":\"p\",\"content\":\"Внутри `body` я создаю первый блок `div`, его мы будем называть шапкой. Он практически ничем не отличается от других блоков `div`, почему он будет являться шапкой? Потому что мы так договорились.\"},{\"block\":\"p\",\"content\":\"Следующий блок `div` — это содержимое. Последний блок `div` — подвал или footer.\"},{\"block\":\"h2\",\"content\":\"Добавим стилей\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<!DOCTYPE html>\\n<html lang=\\\"ru\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n    <title>Document</title>\\n</head>\\n<body>\\n    <div style=\\\"background-color: lightblue; padding: 12px; text-align: center;\\\">\\n        <h1>Привет!</h1>\\n    </div>\\n    <div style=\\\"padding-top: 20px; padding-bottom: 20px;\\\">\\n        <p>Это мой первый сайт</p>\\n    </div>\\n    <div style=\\\"border-top: 1px solid #ccc; padding: 10px; text-align: center;\\\">\\n        <p>Все права защищены</p>\\n    </div>\\n</body>\\n</html>\"},{\"block\":\"img\",\"src\":\"/img/courses/html-css-first-site/4-2.jpg\",\"alt\":\"Страница с оформленной шапкой и подвалом\"},{\"block\":\"p\",\"content\":\"Теперь шапка с фоном, содержимое имеет отступы `padding`, а подвал отделен от контента при помощи верхней черты.\"}]},{\"slug\":\"5\",\"title\":\"5. Семантические теги и SEO\",\"short\":\"Семантические теги и SEO\",\"content\":[{\"block\":\"p\",\"content\":\"Мы создали шапку, содержимое и подвал. Все они являются тегом `div`. Люди могут отличить что есть что, а вот роботы — нет. У них нет глаз и они не могут посмотреть, что вы имели ввиду под блоком `div`.\"},{\"block\":\"h2\",\"content\":\"Поисковая выдача\"},{\"block\":\"p\",\"content\":\"Почему роботу нужно знать, что вы имели ввиду под блоком `div`? Потому что роботы занимаются индексацией сайтов. Проще говоря, ваш сайт может попасть в выдачу в поисковике. Есть отдельное направление, которое занимается тем, чтобы страницы сайта попадались как можно выше в поисковой выдаче. Потому что люди чаще всего не открывают сайты напрямую, а ищут их по запросам в интернете. Ну, кроме меня.\"},{\"block\":\"note\",\"content\":\"Не бойтесь: сейчас ваш сайт, а вернее его страница, не может попасть в поисковую выдачу, потому что ваш сайт не размещен в интернете. Сделаем это позже.\"},{\"block\":\"h2\",\"content\":\"SEO оптимизация\"},{\"block\":\"p\",\"content\":\"Направление, которое занимается настройкой выдачи страниц называется SEO. И чтобы сайт оказывался как можно выше в поисковой выдаче, его нужно SEO оптимизировать.\"},{\"block\":\"p\",\"content\":\"SEO оптимизация — это отдельная большая тема, но мы можем сделать маленький шаг в этом направлении. Давайте заменим наши блоки `div` на их аналоги.\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<!DOCTYPE html>\\n<html lang=\\\"ru\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n    <title>Document</title>\\n</head>\\n<body>\\n    <header style=\\\"background-color: lightblue; padding: 12px; text-align: center;\\\">\\n        <h1>Привет!</h1>\\n    </header>\\n    <main style=\\\"padding-top: 20px; padding-bottom: 20px;\\\">\\n        <p>Это мой первый сайт</p>\\n    </main>\\n    <footer style=\\\"border-top: 1px solid #ccc; padding: 10px; text-align: center;\\\">\\n        <p>Все права защищены</p>\\n    </footer>\\n</body>\\n</html>\"},{\"block\":\"p\",\"content\":\"Я заменил все `div` на их аналоги. Для шапки мы будем использовать тег `header`. Для содержимого сайта тег `main`. А для подвала тег `footer`. Не беспокойтесь, это точно такие же `div`, просто называются по-другому.\"},{\"block\":\"p\",\"content\":\"Теперь поисковые роботы точно смогут понять, что шапка — это шапка.\"},{\"block\":\"h3\",\"content\":\"Улучшение поисковой выдачи\"},{\"block\":\"p\",\"content\":\"Раз уж я заговорил про SEO оптимизацию, давайте расскажу основные моменты, которые на нее влияют.\"},{\"block\":\"p\",\"content\":\"Ключевое что влияет на поисковую выдачу — это заголовки страниц. Изменить заголовок мы можем при помощи тега `title` внутри тега `head`. Давайте изменим его на «Мой первый сайт».\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n    <title>Мой первый сайт</title>\\n</head>\"},{\"block\":\"p\",\"content\":\"Также внутри тега `head` мы можем добавить описание страницы, ключевые слова и другие мета-теги. Все это помогает поисковым роботам лучше проанализировать ваш сайт. Подробнее про это можно почитать на [документации MDN](https://developer.mozilla.org/ru/docs/Web/HTML/Element/meta).\"},{\"block\":\"h2\",\"content\":\"Выносим стили в тег style\"},{\"block\":\"p\",\"content\":\"Для красоты можем вынести стили в тег `style`.\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<!DOCTYPE html>\\n<html lang=\\\"ru\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\">\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n    <title>Document</title>\\n    <style>\\n        header {\\n            background-color: lightblue;\\n            padding: 12px;\\n            text-align: center;\\n        }\\n        main {\\n            padding-top: 20px;\\n            padding-bottom: 20px;\\n        }\\n        footer {\\n            border-top: 1px solid #ccc;\\n            padding: 10px;\\n            text-align: center;\\n        }\\n    </style>\\n</head>\\n<body>\\n    <header>\\n        <h1>Привет!</h1>\\n    </header>\\n    <main>\\n        <p>Это мой первый сайт</p>\\n    </main>\\n    <footer>\\n        <p>Все права защищены</p>\\n    </footer>\\n</body>\\n</html>\"},{\"block\":\"p\",\"content\":\"Теперь все красиво.\"}]},{\"slug\":\"6\",\"title\":\"6. Картинки, ссылки и новые страницы\",\"short\":\"Картинки, ссылки и новые страницы\",\"content\":[{\"block\":\"p\",\"content\":\"Ну что, мы почти все знаем, чтобы создать свою страницу для сайта. Создавать их умеем, добавлять теги тоже, даже стили написать можем. Остается дело за малым — вам необходимо самостоятельно познакомиться с разными тегами и их назначениями, понять как создавать верстку страниц. И набраться опыта. Ничего сложного в этом нет, просто дело времени и практики.\"},{\"block\":\"h2\",\"content\":\"Задание\"},{\"block\":\"note\",\"content\":\"Наполните нашу абстрактную страницу настоящим содержимым. К примеру, создайте страницу-биографию о вас, с шапкой, заголовками, текстом и картинками.\"},{\"block\":\"h2\",\"content\":\"Изображения\"},{\"block\":\"p\",\"content\":\"Ах да, мы не научились создавать картинки. Все очень просто. Скачивайте картинку которая вам понравилась. И разместите в папке, где находится ваша страница сайта.\"},{\"block\":\"p\",\"content\":\"Чтобы добавить картинку на страницу нужно создать тег `img` и в атрибуте `src` указать путь к изображению. По умолчанию путь считается от текущей папки.\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<img src=\\\"example.png\\\" />\"},{\"block\":\"h2\",\"content\":\"Новые страницы\"},{\"block\":\"p\",\"content\":\"Сайт — это, как правило, несколько страниц. Создадим новую страницу. Для этого нужно создать новый файл с расширением `.html`, к примеру `about.html`.\"},{\"block\":\"p\",\"content\":\"Новая страница создается точно также. Чтобы с прошлой страницы нам сослаться на новую, нужно создать ссылку.\"},{\"block\":\"code\",\"language\":\"HTML\",\"content\":\"<a href=\\\"about.html\\\">Обо мне</a>\"},{\"block\":\"p\",\"content\":\"Ссылка создается при помощи тега `a`, атрибут `href` указывает путь до новой страницы, в нашей случае — файла, а содержимое тега `a` — это текст ссылки.\"},{\"block\":\"p\",\"content\":\"Теперь вы можете творить. Приступайте!\"}]},{\"slug\":\"7\",\"title\":\"7. Публикация сайта в интернете\",\"short\":\"Публикация сайта в интернете\",\"content\":[{\"block\":\"p\",\"content\":\"Теперь у нас есть свой собственный сайт. Созданный самостоятельно. По своим правилам. Давайте сделаем его публично доступным. Сейчас у вас просто файлы сайта, но в интернете он еще недоступен публично.\"},{\"block\":\"h2\",\"content\":\"Регистрация на GitHub\"},{\"block\":\"p\",\"content\":\"Есть множество разных способов размещения сайта в интернете. Платные и бесплатные. Начнем с бесплатного.\"},{\"block\":\"p\",\"content\":\"Для этого необходимо создать аккаунт на GitHub: [https://github.com](https://github.com)\"},{\"block\":\"p\",\"content\":\"После того, как регистрация прошла успешно, нам нужно создать репозиторий, это как бы и есть наш сайт. Не совсем, но сейчас это неважно: [https://github.com/new](https://github.com/new)\"},{\"block\":\"p\",\"content\":\"Даем название репозиторию и создаем его.\"},{\"block\":\"img\",\"src\":\"/img/courses/html-css-first-site/7-1.jpg\",\"alt\":\"Создание репозитория на GitHub\"},{\"block\":\"p\",\"content\":\"Когда все получится, вы увидите такую страницу. Здесь много разного текста, но для нас это все неважно.\"},{\"block\":\"h2\",\"content\":\"Загружаем файлы сайта\"},{\"block\":\"p\",\"content\":\"Необходимо немного изменить ссылку в адресной строке. К примеру, страница которую вы видите у меня располагается по адресу: `https://github.com/DanyaBooba/example-site`\"},{\"block\":\"p\",\"content\":\"Где `DanyaBooba` — мой никнейм, `example-site` — название репозитория.\"},{\"block\":\"p\",\"content\":\"В конец данной ссылки необходимо добавить «/upload». Получится вот так: `https://github.com/DanyaBooba/example-site/upload`\"},{\"block\":\"img\",\"src\":\"/img/courses/html-css-first-site/7-2.jpg\",\"alt\":\"Страница загрузки файлов в репозиторий\"},{\"block\":\"p\",\"content\":\"И мы попадем уже на такую страницу. Сюда необходимо перетащить все страницы и файлы нашего сайта, чтобы они сохранились в репозитории.\"},{\"block\":\"note\",\"content\":\"Важно: перемещать нужно не папку с файлами (страницами, картинками и прочим), а именно сами файлы страниц, картинок и прочего.\"},{\"block\":\"p\",\"content\":\"Как загрузили, нажимаем на зеленую кнопку внизу.\"},{\"block\":\"img\",\"src\":\"/img/courses/html-css-first-site/7-3.jpg\",\"alt\":\"Кнопка подтверждения загрузки файлов\"},{\"block\":\"h2\",\"content\":\"Включаем GitHub Pages\"},{\"block\":\"p\",\"content\":\"Почти готово. Теперь нужно открыть настройки репозитория.\"},{\"block\":\"img\",\"src\":\"/img/courses/html-css-first-site/7-4.jpg\",\"alt\":\"Настройки репозитория в шапке\"},{\"block\":\"p\",\"content\":\"Располагаются они в шапке вверху.\"},{\"block\":\"img\",\"src\":\"/img/courses/html-css-first-site/7-5.jpg\",\"alt\":\"Раздел Pages в настройках\"},{\"block\":\"p\",\"content\":\"Далее, слева необходимо выбрать пункт «Pages», с англ. «Страницы». Здесь указано, что при помощи GitHub Pages мы можем публично разместить наш сайт через репозиторий. Что мы и делаем.\"},{\"block\":\"p\",\"content\":\"Чтобы разместить сайт необходимо выбрать в блоке «Branch» значение «main».\"},{\"block\":\"img\",\"src\":\"/img/courses/html-css-first-site/7-6.jpg\",\"alt\":\"Выбор ветки main\"},{\"block\":\"p\",\"content\":\"Потом нажимаем на кнопку «Save». И ждем минуту.\"},{\"block\":\"img\",\"src\":\"/img/courses/html-css-first-site/7-7.jpg\",\"alt\":\"Кнопка Save\"},{\"block\":\"p\",\"content\":\"После ожидания вверху страницы появится такой блок.\"},{\"block\":\"img\",\"src\":\"/img/courses/html-css-first-site/7-8.jpg\",\"alt\":\"Блок со ссылкой на опубликованный сайт\"},{\"block\":\"h2\",\"content\":\"Готово\"},{\"block\":\"p\",\"content\":\"Поздравляю! Теперь ваш сайт публично размещен в интернете. Нажмите на кнопку «Visit site», чтобы открыть его.\"},{\"block\":\"p\",\"content\":\"Ссылка на ваш сайт строится следующим образом, посмотрим в качестве примера на мою: [https://danyabooba.github.io/example-site/](https://danyabooba.github.io/example-site/)\"},{\"block\":\"p\",\"content\":\"`danyabooba` — никнейм, `example-site` — название репозитория.\"},{\"block\":\"p\",\"content\":\"Вы можете создать новый репозиторий и разместить на нем новый сайт, тогда `example-site` заменится на новое название.\"},{\"block\":\"p\",\"content\":\"Если захотите обновить сайт, достаточно загрузить новые файлы в репозиторий и они заменят старые. Сайт будет обновлен.\"}]},{\"slug\":\"8\",\"title\":\"8. Что делать дальше\",\"short\":\"Что делать дальше\",\"content\":[{\"block\":\"p\",\"content\":\"Поздравляю! Вы создали свой первый сайт. На этом курсе мы познакомились с HTML и CSS, научились создавать страницы и размещать их в интернете. Дальше вы можете продолжать изучать HTML и CSS, а также JavaScript. А также создавать свои сайты и размещать их в интернете.\"},{\"block\":\"h2\",\"content\":\"Продолжить изучение\"},{\"block\":\"p\",\"content\":\"Для продолжения изучения HTML, CSS и ознакомления с JavaScript могу предложить следующие курсы:\"},{\"block\":\"courses\",\"items\":[\"vanilla-javascript\",\"gulp-workflow\",\"web-media\"]},{\"block\":\"p\",\"content\":\"А также могу порекомендовать следующие ресурсы:\"},{\"block\":\"ul\",\"items\":[\"[Дока](https://doka.guide) — отличная документация по вебу с примерами\",\"[MDN](https://developer.mozilla.org/ru/docs/Web/) — более строгая документация по вебу, но с большим количеством информации\",\"[HTML Academy](https://htmlacademy.ru/) — интерактивные курсы по HTML, CSS и JavaScript\",\"[W3Schools](https://w3schools.com/) — очень подробная документация по вебу, но с устаревшими примерами и советами\"]},{\"block\":\"p\",\"content\":\"Самое главное — не останавливаться на достигнутом. Продолжайте изучать веб и создавать свои сайты. Удачи!\"}]},{\"slug\":\"end\",\"title\":\"Проверка усвоенного\",\"short\":\"Проверка усвоенного\",\"content\":[{\"block\":\"p\",\"content\":\"Курс пройден: страница свёрстана и опубликована. Осталось проверить себя — сначала вопросы по материалу, а потом чек-лист по вашему готовому сайту.\"},{\"block\":\"quiz\",\"quiz\":{\"title\":\"Вопросы по курсу\",\"intro\":\"Десять вопросов по всем урокам. Оценка нигде не сохраняется. Тест нужен для вас, чтобы увидеть пробелы в знаниях. После проверки к каждому вопросу появится разбор.\",\"questions\":[{\"id\":\"q1\",\"question\":\"Внутри какого тега пишут содержимое, которое видно на странице?\",\"options\":[\"<head>\",\"<body>\",\"<title>\",\"<!DOCTYPE html>\"],\"correct\":[1],\"hint\":\"В <head> лежат служебные данные, их на странице не видно. Видимая часть — всё, что внутри <body>.\"},{\"id\":\"q2\",\"question\":\"Какие теги одинарные — то есть не имеют закрывающего?\",\"options\":[\"<meta>\",\"<img>\",\"<p>\",\"<div>\"],\"correct\":[0,1],\"hint\":\"Закрывающий тег нужен там, куда можно положить содержимое. В <meta> и <img> класть нечего — путь к картинке и настройки передаются атрибутами.\"},{\"id\":\"q3\",\"question\":\"Чем атрибут class отличается от атрибута style?\",\"options\":[\"class задаёт имя, по которому стили находят элемент, а style задаёт сами стили прямо в теге\",\"Это одно и то же, просто разные способы записи\",\"class работает только для текста, а style — для блоков\",\"class задаёт цвет, а style — размер\"],\"correct\":[0],\"hint\":\"Сам по себе class ничего не оформляет. Это метка: вы пишете class=\\\"paragraph\\\", а потом в CSS описываете .paragraph — и стили находят нужный элемент по этой метке.\"},{\"id\":\"q4\",\"question\":\"Как в CSS обратиться ко всем элементам с классом paragraph?\",\"options\":[\"paragraph { }\",\".paragraph { }\",\"#paragraph { }\",\"<paragraph> { }\"],\"correct\":[1],\"hint\":\"Перед именем класса ставится точка. Без точки это был бы селектор по названию тега.\"},{\"id\":\"q5\",\"question\":\"Внутри какого тега размещают блок стилей <style>?\",\"options\":[\"<head>\",\"<body>\",\"<footer>\",\"<html>, до <head>\"],\"correct\":[0],\"hint\":\"Стили — служебная часть страницы, поэтому им место в <head>, рядом с <meta> и <title>.\"},{\"id\":\"q6\",\"question\":\"К чему применится правило p { font-weight: bold; }?\",\"options\":[\"Ко всем параграфам на странице\",\"Только к первому параграфу\",\"Только к параграфам с классом p\",\"Ко всем тегам на странице\"],\"correct\":[0],\"hint\":\"Селектор по названию тега действует на все такие теги — и на уже написанные, и на те, что вы добавите позже.\"},{\"id\":\"q7\",\"question\":\"Зачем шапку страницы верстать тегом <header>, а не <div>?\",\"options\":[\"Тег сообщает роль блока браузеру и программам чтения с экрана\",\"Такая страница автоматически поднимается в поисковой выдаче\",\"<header> быстрее загружается\",\"<header> сам добавляет отступы и фон\"],\"correct\":[0],\"hint\":\"Выглядят они одинаково, но <header> объявляет назначение блока. Это помогает незрячим людям перемещаться по странице и делает код понятнее. Волшебного роста в поиске от одной замены тега не будет.\"}]}},{\"block\":\"checklist\",\"title\":\"Чек-лист: проверьте свой сайт\",\"items\":[\"В теге `<title>` стоит название вашей страницы, а не `Document` — именно этот текст виден на вкладке браузера\",\"У тега `<html>` стоит `lang=\\\"ru\\\"`, а не `lang=\\\"en\\\"`\",\"Шапка, содержимое и подвал свёрстаны тегами `header`, `main` и `footer`\",\"Стили вынесены в тег `<style>`, а не раскиданы по атрибутам `style`\"]},{\"block\":\"h2\",\"content\":\"Что дальше\"},{\"block\":\"p\",\"content\":\"Дальше — практика. Возьмите любую страницу, которая вам нравится, и попробуйте повторить её вёрстку. По ходу дела будут всплывать теги и свойства, которых мы не проходили: смотрите их в [документации MDN](https://developer.mozilla.org/ru/docs/Web/HTML/Element) или на [«Доке»](https://doka.guide/html/).\"},{\"block\":\"p\",\"content\":\"Следующий шаг после вёрстки — оживить страницу: обработка нажатий, работа с элементами, запросы к серверу. Это курс «Применение чистого JavaScript на сайте», он появится в каталоге.\"}]}]',
        @owner, 1, '2020-01-01 00:03:00', NOW())
