-- Разработка мобильного приложения: 3 стр.
INSERT INTO courses (id, title, subtitle, accent, section, difficulty, level, duration, image, video, chips, github, author, certificate, about, pages, user_id, disabled, created_at, updated_at)
VALUES ('mobile-app',
        'Разработка мобильного приложения',
        'Приложение для телефона: экраны, навигация, хранение данных и работа с сетью.',
        'expo',
        'mobile',
        4,
        'Нужны основы программирования',
        '11 уроков',
        NULL,
        NULL,
        '[\"React Native\",\"Expo\"]',
        NULL,
        '{\"name\":\"Даниил Дыбка\",\"email\":\"daniil@dybka.ru\",\"telegram\":\"https://ddybka.t.me\"}',
        NULL,
        '[{\"block\":\"p\",\"content\":\"Приложение для телефона: экраны, навигация, хранение данных и работа с сетью.\"},{\"block\":\"note\",\"content\":\"Курс в разработке. Материалы появятся здесь, как только будут готовы.\"},{\"block\":\"h2\",\"content\":\"Чему вы научитесь\"},{\"block\":\"ul\",\"items\":[\"Проектирование экранов и навигации между ними.\",\"Списки, формы и состояния загрузки.\",\"Работа с сетью и обработка ошибок соединения.\",\"Локальное хранение данных и офлайн-режим.\",\"Иконка, сплэш-экран и подготовка к публикации.\"]},{\"block\":\"h2\",\"content\":\"Результат\"},{\"block\":\"p\",\"content\":\"Рабочее приложение, установленное на ваш телефон.\"}]',
        '[{\"slug\":\"1\",\"title\":\"1. Введение\",\"short\":\"Введение\",\"content\":[{\"block\":\"p\",\"content\":\"На этом курсе мы разберёмся, как разрабатывать мобильные приложения. Курс рассчитан на тех, у кого есть навыки основ программирования и кто владеет фреймворком React.\"},{\"block\":\"p\",\"content\":\"Если с React вы ещё не знакомы, начните с этого курса:\"},{\"block\":\"courses\",\"items\":[\"react-site\"]},{\"block\":\"h2\",\"content\":\"Небольшая историческая справка\"},{\"block\":\"p\",\"content\":\"9 января 2007 года в 9:41 Стив Джобс презентовал первый в мире iPhone. Он совершил революцию и стал для Apple культовым устройством, заменив собой плеер iPod — главный продукт компании на тот момент.\"},{\"block\":\"p\",\"content\":\"На первом iPhone не было магазина приложений, это известный факт. Стив Джобс считал, что мобильные приложения не нужны: веб активно развивался, и все приложения можно было держать в браузере, то есть использовать веб-приложения.\"},{\"block\":\"p\",\"content\":\"Но люди не приняли такой сценарий: все хотели привычные приложения, которые вовсю разрабатывались, использовались и распространялись на Android.\"},{\"block\":\"p\",\"content\":\"В итоге Стив Джобс сдался, и во втором iPhone, который был назван 3G, появился магазин приложений — App Store.\"},{\"block\":\"h2\",\"content\":\"Зачем нужны мобильные приложения\"},{\"block\":\"p\",\"content\":\"Сейчас история повторяется: веб продолжает активно развиваться, и может показаться, что мобильные приложения уже в прошлом. Так ли это на самом деле? Нет.\"},{\"block\":\"p\",\"content\":\"Приложения остаются востребованными даже с развитием веба. Всё дело в удобстве: не нужно ждать загрузки сайта, чтобы посмотреть сообщения или открыть календарь. Приложения, как правило, работают удобнее, потому что используют системные стили в интерфейсе. А ещё приложения могут использовать нативные модули устройства: уведомления, звонки, работу с кэшем.\"},{\"block\":\"p\",\"content\":\"Веб-сайты открываются через браузер, который может потреблять много ресурсов и не даёт полного доступа к устройству. Поэтому люди всё так же любят приложения и часто ими пользуются.\"}]},{\"slug\":\"2\",\"title\":\"2. Выбор технологий\",\"short\":\"Выбор технологий\",\"content\":[{\"block\":\"p\",\"content\":\"Перейдём к разработке приложения. Начнём с выбора стека технологий. Мобильные приложения можно писать с помощью разных инструментов — разберём каждый из них.\"},{\"block\":\"h2\",\"content\":\"Нативная разработка на Xcode / Android Studio\"},{\"block\":\"p\",\"content\":\"Первое, что приходит в голову при выборе технологии для мобильных приложений, — использовать нативные средства Apple и Google.\"},{\"block\":\"p\",\"content\":\"Приложения для устройств Apple пишут в программе Xcode, которая доступна только на Mac. Приложения для Android — в Android Studio, которая работает на большем количестве ОС.\"},{\"block\":\"p\",\"content\":\"Плюс такого решения очевиден: вы создаёте приложения так, как задумали создатели платформы, среди первых получаете обновления и не используете лишних мостов при разработке.\"},{\"block\":\"note\",\"content\":\"Под мостами я понимаю ситуацию, когда выбранная технология не позволяет полностью раскрыть ваш потенциал, и приходится опускаться на уровень ниже. Например, для Python некоторые библиотеки написаны на языке C: Python медленный, а код на C выполняется гораздо быстрее. Так делают, к примеру, при чтении файлов или работе с массивами.\"},{\"block\":\"p\",\"content\":\"Но есть и минус. Вам придётся отдельно учить, возможно, новый язык программирования и разбираться, как правильно пользоваться выбранными программами.\"},{\"block\":\"p\",\"content\":\"Обучение — наш девиз у программистов, мы постоянно чему-то учимся. Если время позволяет, конечно, лучше разрабатывать нативными средствами.\"},{\"block\":\"p\",\"content\":\"Второй минус — приложение придётся создавать отдельно для устройств Apple и отдельно для Android. Общего кода между ними не будет.\"},{\"block\":\"p\",\"content\":\"Исходя из минусов, думаем дальше.\"},{\"block\":\"h2\",\"content\":\"Flutter и Dart\"},{\"block\":\"p\",\"content\":\"В последнее время я часто замечаю, что мобильные приложения создают на языке Dart и фреймворке Flutter.\"},{\"block\":\"p\",\"content\":\"Эту технологию придумали в компании Google, той самой корпорации добра.\"},{\"block\":\"p\",\"content\":\"Что важно сказать: использовать нативные элементы дизайна из ОС в интерфейсе у вас не выйдет. То есть интерфейс на iOS и Android будет выглядеть одинаково. Иногда компании так и делают, но я больше любитель натива, чтобы интерфейс поддерживал системные элементы — например, Liquid Glass на iOS и Material 3 на Android.\"},{\"block\":\"p\",\"content\":\"Ещё один минус для меня — нужно отдельно учить новый язык Dart. Да, он похож на TypeScript, который, в свою очередь, похож на JavaScript. Но похож не значит равен. Почти наверняка возникнут трудности и подводные камни, из-за которых разработка затянется.\"},{\"block\":\"p\",\"content\":\"Возможно, когда-нибудь я изучу Flutter и Dart и смогу подробнее рассказать о них и сравнить со следующей технологией.\"},{\"block\":\"h2\",\"content\":\"React Native и Expo\"},{\"block\":\"p\",\"content\":\"Мой фаворит — React Native и Expo. С их помощью можно разрабатывать по-настоящему нативные приложения с системным интерфейсом и почти ничему новому не учиться, если вы знаете TypeScript и React.\"},{\"block\":\"p\",\"content\":\"React Native, как и React, придумали в компании M*ta (бывш. Fac*book). Позже эти технологии передали некоммерческому фонду React Foundation под эгидой Linux Foundation, и названная компания больше не владеет ими единолично. Развитием технологий занимается группа компаний, в которую входят Amazon, Huawei, Microsoft и другие.\"},{\"block\":\"p\",\"content\":\"Мобильные приложения на React Native и Expo создаются по очень схожим принципам с сайтами на React: такие же компоненты, хуки, провайдеры, такой же TypeScript. Но на выходе мы получаем по-настоящему нативное приложение, а не приложение, запущенное в браузере.\"},{\"block\":\"p\",\"content\":\"React Native и Expo позволяют создавать кроссплатформенные приложения для iOS и Android. Вы пишете один код, а получаете сразу два приложения.\"},{\"block\":\"p\",\"content\":\"А с Expo вы получите ещё и веб-приложение. Получается, из единой кодовой базы выходят сразу три приложения: для Android, iOS и веба.\"},{\"block\":\"h2\",\"content\":\"Итог\"},{\"block\":\"p\",\"content\":\"В рамках этого курса мы будем разрабатывать приложение на React Native и Expo. В следующем уроке начнём с установки программ.\"}]},{\"slug\":\"3\",\"title\":\"3. Установка программ\",\"short\":\"Установка программ\",\"content\":[{\"block\":\"p\",\"content\":\"В прошлом уроке мы выбрали React Native и Expo для разработки мобильного приложения. Теперь приступим к самой разработке и установим всё необходимое.\"},{\"block\":\"h2\",\"content\":\"Установка Node.js\"},{\"block\":\"p\",\"content\":\"Раз уж вы владеете React, то и Node.js у вас установлен. Если нет — скачайте его с официального сайта: [https://nodejs.org/en/download](https://nodejs.org/en/download)\"},{\"block\":\"p\",\"content\":\"Убедиться, что всё на месте, можно командой:\"},{\"block\":\"code\",\"language\":\"Bash\",\"content\":\"node -v\"},{\"block\":\"p\",\"content\":\"Если в терминале напечаталась версия Node.js, едем дальше.\"},{\"block\":\"h2\",\"content\":\"Установка редактора\"},{\"block\":\"p\",\"content\":\"Думаю, редактор у вас тоже уже установлен. Проверьте.\"},{\"block\":\"p\",\"content\":\"Лично я пользуюсь Visual Studio Code — в курсе вы будете видеть именно его.\"},{\"block\":\"h3\",\"content\":\"Устанавливаем расширения\"},{\"block\":\"p\",\"content\":\"Рекомендую установить следующие расширения:\"},{\"block\":\"ul\",\"items\":[\"DotENV от mikestead\",\"ESLint от Microsoft\",\"GitLens — Git supercharged от GitKraken\",\"npm Intellisense от Christian Kohler\",\"React Native Tools от Microsoft\"]},{\"block\":\"p\",\"content\":\"Это необязательно: всё будет работать и без них, просто так удобнее. GitLens устанавливайте, если планируете работать с Git.\"},{\"block\":\"h2\",\"content\":\"Установка Expo Go\"},{\"block\":\"p\",\"content\":\"Чтобы запускать мобильное приложение на самом телефоне, установите на него программу Expo Go. Она есть для iOS и Android.\"},{\"block\":\"h2\",\"content\":\"Установка симулятора\"},{\"block\":\"p\",\"content\":\"Насчёт симулятора есть два важных момента:\"},{\"block\":\"ul\",\"items\":[\"Приложение можно запускать через Expo Go на самом телефоне. Но если в приложении есть сложные модули (например, карта или уведомления), Expo Go не сможет запустить проект, и придётся использовать симулятор.\",\"Симуляторы занимают немало места (15–20 ГБ и больше), потому что требуют установки Xcode и/или Android Studio.\"]},{\"block\":\"p\",\"content\":\"Поэтому решите сами, нужен ли вам симулятор. Если у вас есть телефон с Expo Go, поначалу симулятор не понадобится.\"},{\"block\":\"h3\",\"content\":\"Установка Xcode\"},{\"block\":\"p\",\"content\":\"Если у вас есть Mac (MacBook, iMac, Mac mini, Mac Studio и другие), вы сможете установить Xcode и вместе с ним симулятор iOS.\"},{\"block\":\"p\",\"content\":\"Установить Xcode можно из App Store или с официального сайта: [https://developer.apple.com/download/applications/](https://developer.apple.com/download/applications/)\"},{\"block\":\"p\",\"content\":\"Лучше выбирайте стабильную сборку (не бету) и обратите внимание на версию macOS. Последнюю версию Xcode можно установить только на последнюю версию macOS. А поддержка iOS внутри Xcode зависит от версии программы, которая, в свою очередь, зависит от macOS…\"},{\"block\":\"note\",\"content\":\"Короче, если ваш Mac слишком старый, актуальную версию Xcode установить не получится. Обратите на это внимание.\"},{\"block\":\"p\",\"content\":\"При первом запуске Xcode сам предложит установить iOS — выберите нужную версию. Скачать новый симулятор можно в настройках, в пункте Components.\"},{\"block\":\"img\",\"src\":null},{\"block\":\"p\",\"content\":\"В Xcode вы устанавливаете iOS и можете выбрать для запуска любое устройство (iPhone или iPad), которое поддерживает эту версию. Отдельно устанавливать «устройство» не нужно — только iOS.\"},{\"block\":\"h3\",\"content\":\"Установка Android Studio\"},{\"block\":\"p\",\"content\":\"Для симулятора Android нужна Android Studio — она есть не только на Windows. Переходим на официальный сайт: [https://developer.android.com/studio?hl=ru](https://developer.android.com/studio?hl=ru)\"},{\"block\":\"p\",\"content\":\"Скачиваем и устанавливаем.\"},{\"block\":\"img\",\"src\":null},{\"block\":\"p\",\"content\":\"После установки симуляторы можно найти в разделе More Actions > Virtual Device Manager.\"},{\"block\":\"img\",\"src\":null},{\"block\":\"p\",\"content\":\"Плюсик в левом верхнем углу добавляет новый симулятор. Здесь скачивается уже конкретная модель телефона: так же легко переключаться между устройствами, как в Xcode, не получится — каждое нужно сначала установить.\"},{\"block\":\"img\",\"src\":null},{\"block\":\"p\",\"content\":\"Среди всех устройств выбираем понравившееся и нажимаем Next.\"},{\"block\":\"img\",\"src\":null},{\"block\":\"p\",\"content\":\"Здесь симулятор можно настроить: дать ему название, посмотреть характеристики. После этого устанавливаем.\"},{\"block\":\"h2\",\"content\":\"Итог\"},{\"block\":\"p\",\"content\":\"Отлично, в этом уроке мы установили все необходимые программы. В следующем начнём разработку.\"}]}]',
        @owner, 1, '2020-01-01 00:10:00', '2026-09-10 00:00:00')
