-- Публикация игры и приложения в маркеты: 1 стр.
INSERT INTO courses (id, title, subtitle, accent, section, difficulty, level, duration, image, video, chips, github, author, certificate, about, pages, user_id, disabled, created_at, updated_at)
VALUES ('store-publishing',
        'Публикация игры и приложения в маркеты',
        'Как довести проект до магазина: подписи, требования, описания, скриншоты и обновления.',
        'amber',
        'mobile',
        1,
        'Для всех',
        '6 уроков',
        NULL,
        NULL,
        '[\"Google Play\",\"App Store\",\"Релиз\",\"Чек-лист\"]',
        NULL,
        '{\"name\":\"Даниил Дыбка\",\"email\":\"daniil@dybka.ru\",\"telegram\":\"https://ddybka.t.me\"}',
